export const content: string = "# \ucf54\uc2a4\ud1a8\ub77c\ub2c8 2\uad8c \u2014 \ud22c\uc790\ub294 \uc2ec\ub9ac\uac8c\uc784\uc774\ub2e4 (\uc6d0\ubb38 \uc815\ub9ac\ubcf8)\n\n---\n\n## \ubaa9\ucc28\n\n1. [\ub4e4\uc5b4\uac00\uba70 \u2014 \uc8fc\uc2dd\ud22c\uc790\ub294 \uc65c \uc624\uc9d5\uc5b4 \uac8c\uc784\uc778\uac00](#\ub4e4\uc5b4\uac00\uba70)\n2. [\ud3ec\uc778\ud2b8 1 \u2014 \ubc18\ub4dc\uc2dc \uc77d\uc5b4\uc57c \ud560 \ucc45](#\ud3ec\uc778\ud2b8-1)\n3. [\ud3ec\uc778\ud2b8 2 \u2014 80\uc138\uc640 20\uc138\uc758 \ub300\ud654](#\ud3ec\uc778\ud2b8-2)\n4. [\ud3ec\uc778\ud2b8 3 \u2014 \uc99d\uad8c\uc2dc\uc7a5\uc758 90%\ub294 \uc2ec\ub9ac\ud559\uc774\ub2e4](#\ud3ec\uc778\ud2b8-3)\n5. [\ud3ec\uc778\ud2b8 4 \u2014 \uc5ec\uc804\ud788 \ubd88\ud22c\uba85\ud55c \uc99d\uad8c\uc2dc\uc7a5](#\ud3ec\uc778\ud2b8-4)\n6. [\ud3ec\uc778\ud2b8 5 \u2014 \uc124\uba85\uc740 \uc5b8\uc81c\ub098 \ub098\uc911\uc5d0 \ub530\ub77c\uc628\ub2e4](#\ud3ec\uc778\ud2b8-5)\n7. [\ud3ec\uc778\ud2b8 6 \u2014 \ube44\uad00\uc8fc\uc758\uc790\ub4e4\uc758 \ud2b9\uc9d5](#\ud3ec\uc778\ud2b8-6)\n8. [\ud3ec\uc778\ud2b8 7 \u2014 \ud070 \uc190\uc5d0\uc11c \uc791\uc740 \uc190\uc73c\ub85c\uc758 \uc774\ub3d9](#\ud3ec\uc778\ud2b8-7)\n9. [\ud3ec\uc778\ud2b8 8 \u2014 \uc2ec\uc0ac\uc219\uace0, \ub17c\ub9ac, \uc815\ud655\uc131](#\ud3ec\uc778\ud2b8-8)\n10. [\ud3ec\uc778\ud2b8 9 \u2014 \ub3c8\uc758 \ub9e4\ub825](#\ud3ec\uc778\ud2b8-9)\n11. [\ud3ec\uc778\ud2b8 10 \u2014 \ud604\uae08\uc744 \uac00\uc838\ub77c](#\ud3ec\uc778\ud2b8-10)\n12. [\ud3ec\uc778\ud2b8 11 \u2014 \ucee4\ub2e4\ub780 \uce74\uc9c0\ub178\uc5d0\uc11c\uc758 \uccab \uc131\uacf5](#\ud3ec\uc778\ud2b8-11)\n13. [\ud3ec\uc778\ud2b8 12 \u2014 \uc790\uc720\ub85c\uc6b4 \ud22c\uc790\uc790](#\ud3ec\uc778\ud2b8-12)\n14. [\ud3ec\uc778\ud2b8 13 \u2014 \ube5a\uc9c0\uc9c0 \ub9c8\ub77c](#\ud3ec\uc778\ud2b8-13)\n15. [\ud3ec\uc778\ud2b8 14 \u2014 \uc99d\uad8c\uc2dc\uc7a5\uc740 \uc628\ud1b5 \uc815\uc2e0\ubcd1\uc790\ub4e4\ub85c \ub4a4\ub36e\uc5ec \uc788\ub2e4](#\ud3ec\uc778\ud2b8-14)\n16. [\ud3ec\uc778\ud2b8 15 \u2014 \uc2dc\uc138 \ubd80\uc591\uc790\uc640 \uac1c\ubbf8](#\ud3ec\uc778\ud2b8-15)\n17. [\ud3ec\uc778\ud2b8 16 \u2014 \ub2e8\uae30\uc801\uc73c\ub85c \uacbd\uc81c \uc0c1\ud669\uc740 \uc2dc\uc138\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc9c0 \ubabb\ud55c\ub2e4](#\ud3ec\uc778\ud2b8-16)\n18. [\ud3ec\uc778\ud2b8 17 \u2014 \uc7a5\uae30\uc801 \ucd94\uc138\uc640 \uae30\uc5c5 \ud380\ub354\uba58\ud138](#\ud3ec\uc778\ud2b8-17)\n19. [\ud3ec\uc778\ud2b8 18 \u2014 \uc2dc\uc138\ub294 \ub3c8 + \uc2ec\ub9ac](#\ud3ec\uc778\ud2b8-18)\n20. [\ud3ec\uc778\ud2b8 19 \u2014 PER\uc744 \uad6c\uad6c\ub2e8\ucc98\ub7fc \uc678\uc9c0 \ub9c8\ub77c](#\ud3ec\uc778\ud2b8-19)\n21. [\ud3ec\uc778\ud2b8 20 \u2014 \uc77c\uc0c1\uc758 \ub17c\ub9ac\uc640 \ub2e4\ub978 \uc99d\uad8c\uc2dc\uc7a5\uc758 \ub17c\ub9ac](#\ud3ec\uc778\ud2b8-20)\n22. [\ud3ec\uc778\ud2b8 21 \u2014 \uc99d\uad8c\uc2dc\uc7a5\uc774 \ub17c\ub9ac\uc801\uc774\uc9c0 \uc54a\uc740 \uacb0\uc815\uc801 \uc774\uc720 \u2014 \ud329\ud140 \ucf64\ud50c\ub9ac](#\ud3ec\uc778\ud2b8-21)\n23. [\ud3ec\uc778\ud2b8 22 \u2014 \ud329\ud140 \ucf64\ud50c\ub9ac\uc758 \uacb0\ub860](#\ud3ec\uc778\ud2b8-22)\n24. [\ud3ec\uc778\ud2b8 23 \u2014 \uc2ec\ub9ac vs. \ud380\ub354\uba58\ud138](#\ud3ec\uc778\ud2b8-23)\n25. [\ud3ec\uc778\ud2b8 24 \u2014 \uae0d\uc815 vs. \ubd80\uc815, \ub204\uac00 \ub354 \ub9ce\uc740\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4](#\ud3ec\uc778\ud2b8-24)\n26. [\ud3ec\uc778\ud2b8 25 \u2014 \uacb0\uad6d \uc21c\ud658\ud55c\ub2e4, \ub3cc\uace0 \ub3c8\ub2e4](#\ud3ec\uc778\ud2b8-25)\n27. [\ud3ec\uc778\ud2b8 26 \u2014 \uc21c\ud658 \uc18d \ud589\ub3d9 \uc9c0\uce68](#\ud3ec\uc778\ud2b8-26)\n28. [\ud3ec\uc778\ud2b8 27 \u2014 \uc131\uacf5\uc801\uc778 \ud22c\uc790\uc758 \uc804\uc81c \uc870\uac74](#\ud3ec\uc778\ud2b8-27)\n29. [\ud3ec\uc778\ud2b8 28 \u2014 \uacbd\ud5d8\uc73c\ub85c \uc5bb\ub294 \ud310\ub2e8\ub825](#\ud3ec\uc778\ud2b8-28)\n30. [\ud3ec\uc778\ud2b8 29 \u2014 \ub300\uc911 \uc2ec\ub9ac\uc758 \ubc18\uc751\uc740 \uc804\uc5fc\ubcd1\uacfc \uac19\ub2e4](#\ud3ec\uc778\ud2b8-29)\n31. [\ud3ec\uc778\ud2b8 30 \u2014 \ucef4\ud4e8\ud130\uac00 \ud22c\uc790\ub97c \ud560 \uc218 \uc788\uc744\uae4c](#\ud3ec\uc778\ud2b8-30)\n32. [\ud3ec\uc778\ud2b8 31 \u2014 \ub274\uc2a4\ub97c \ucad3\uc9c0 \ub9c8\ub77c](#\ud3ec\uc778\ud2b8-31)\n33. [\ud3ec\uc778\ud2b8 32 \u2014 \uc815\uce58\u00b7\uacbd\uc81c\uc640 \uc99d\uad8c\uc2dc\uc7a5 \ubd84\uc704\uae30](#\ud3ec\uc778\ud2b8-32)\n34. [\ud3ec\uc778\ud2b8 33 \u2014 \ucc45\uc784 \uc788\ub294 \uc790\ub9ac\uc758 \ud55c\ub9c8\ub514](#\ud3ec\uc778\ud2b8-33)\n35. [\ud3ec\uc778\ud2b8 34 \u2014 \ube68\uac04 \uc790\uc804\uac70](#\ud3ec\uc778\ud2b8-34)\n36. [\ud3ec\uc778\ud2b8 35 \u2014 \uc8fc\uc2dd\ud22c\uc790\uac00 \uc7a5\uc548\uc758 \ud654\uc81c\uac00 \ub420 \ub54c](#\ud3ec\uc778\ud2b8-35)\n37. [\ud3ec\uc778\ud2b8 36 \u2014 \ud638\ud669\uae30\uc758 \uc2ec\ub9ac\ud559\uacfc \uad11\uace0](#\ud3ec\uc778\ud2b8-36)\n38. [\ud3ec\uc778\ud2b8 37 \u2014 \uc6f0\ucef4 \ud22c \ub354 \uc815\uae00](#\ud3ec\uc778\ud2b8-37)\n39. [\ud3ec\uc778\ud2b8 38 \u2014 \uc544\uc8fc \uc774\uc0c1\ud55c \uc0ac\ub78c\ub4e4: \uc2dc\uc138 \ud558\ub77d \ud22c\uc790\uc790](#\ud3ec\uc778\ud2b8-38)\n40. [\ud3ec\uc778\ud2b8 39 \u2014 \ub354 \uc774\uc0c1\ud55c \uc0ac\ub78c\ub4e4: \uac8c\uc784\uafbc](#\ud3ec\uc778\ud2b8-39)\n41. [\ud3ec\uc778\ud2b8 40 \u2014 \uc544\uc8fc \ud2b9\uc774\ud55c \ubd80\ub958: \uc21c\uc885 \ud22c\uc790\uc790](#\ud3ec\uc778\ud2b8-40)\n42. [\ud3ec\uc778\ud2b8 41 \u2014 \ubbf8\uc2e0, \uc6b0\uc0c1\uc22d\ubc30, \uc9c1\uad00](#\ud3ec\uc778\ud2b8-41)\n43. [\ud3ec\uc778\ud2b8 42 \u2014 \uc99d\uad8c\uc2dc\uc7a5\uacfc \ub8f0\ub81b, \ubaa8\ub450 \uac8c\uc784\uafbc](#\ud3ec\uc778\ud2b8-42)\n44. [\ud3ec\uc778\ud2b8 43 \u2014 \uc99d\uad8c\uc2dc\uc7a5 \uc911\ub3c5\uc790](#\ud3ec\uc778\ud2b8-43)\n45. [\ud3ec\uc778\ud2b8 44 \u2014 \ubc15\uc2dd\ud55c \ubc14\ubcf4\ub4e4](#\ud3ec\uc778\ud2b8-44)\n46. [\ud3ec\uc778\ud2b8 45 \u2014 \uc815\ub9d0\ub85c \uc0ac\ub791\ud55c\ub2e4\uba74 \ubc29\ubc95\uc744 \uc54c\ub824 \uc918\ub77c](#\ud3ec\uc778\ud2b8-45)\n47. [\ud3ec\uc778\ud2b8 46 \u2014 \ub9c8\uce58\uba70](#\ud3ec\uc778\ud2b8-46)\n\n---\n\n## \ub4e4\uc5b4\uac00\uba70\n\n\uc8fc\uc2dd\ud22c\uc790\ub294 \uc65c \uc624\uc9d5\uc5b4 \uac8c\uc784\uc77c\uae4c? \uc77c\ub2e8 \uac1c\uc5f0\uc131\uc774 \uc5c6\ub2e4. \uc989 \uc5c9\ub9dd\uc9c4\ucc3d\uc774\ub2e4. \uc8fc\uac00\uac00 \uc624\ub974\uace0 \ub0b4\ub9ac\ub294 \uac83\uc5d0 \uc774\uc720\ub97c \ucc3e\uae30\uac00 \ucc38\uc73c\ub85c \uc5b4\ub824\uc6b0\uba70, \ub0b4\uac00 \uc0ac\uba74 \ub5a8\uc5b4\uc9c0\uace0 \ub0b4\uac00 \ud314\uba74 \uc62c\ub77c\uac00\ub294, \ub3c4\ub300\uccb4\uac00 \uc5c9\ub9dd\uc774\ub2e4. \uc624\uc9d5\uc5b4 \uac8c\uc784\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\ub2e4. \uac11\uc790\uae30 \ub531\uc9c0\uce58\uae30\ub97c \ud558\uc9c8 \uc54a\ub098, \ubb34\uad81\ud654\uaf43\uc774 \ud53c\uc5c8\uc2b5\ub2c8\ub2e4\ub97c \ud558\uc9c8 \uc54a\ub098, \ub9c9 \uc2f8\uc6b0\uace0 \uc3d8\uace0 \uc5c9\ub9dd\uc774\ub2e4.\n\n\ucc38\uc5ec\uc790\ub294 \uace0\ud1b5\uc2a4\ub7fd\uace0 \uad00\ub78c\uc790\ub294 \uc7ac\ubbf8\uc788\ub2e4. \uc8fc\uc2dd\uc2dc\uc7a5\uc774\ub098 \uc624\uc9d5\uc5b4 \uac8c\uc784\uc774\ub098 \uc77c\ubc18 \ucc38\uc5ec\uc790\ub294 \uac1c\uc5f0\uc131 \uc5c6\ub294 \uc5c9\ub9dd\uc778 \uac8c\uc784 \uc18d\uc5d0\uc11c \uc815\uc2e0\uc774 \uc5c6\ub2e4. \uc9c4\ud759\ud0d5 \uc2f8\uc6c0\uc5d0\uc11c \uc55e\uc73c\ub85c \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c8\uc9c0 \ubaa8\ub974\ub2c8 \ub2f5\ub2f5\ud558\uace0 \ub450\ub824\uc6b8 \ubfd0\uc774\ub2e4. **\ud558\uc9c0\ub9cc \uadf8 \uc5c9\ub9dd\uc9c4\ucc3d\uc778 \uac8c\uc784\uc5d0\uc11c \ud55c \ubc1c\uc9dd \ub5a8\uc5b4\uc838, \ub09c\uc7a5\ud310 \uc18d \ucc38\uc5ec\uc790\ub4e4\uc758 \ud589\ub3d9\uacfc \uc2ec\ub9ac\ub97c \uc9c0\ucf1c\ubcf4\ub294 \uc774\ub4e4\uc740 \uadf8\uc800 \uc7ac\ubbf8\uc788\ub2e4.**\n\n\uc624\uc9d5\uc5b4 \uac8c\uc784\uc5d0\uc11c \uadf8\ub7f0 \uc778\ubb3c\uc774 \uc624\uc77c\ub0a8\uc774\ub77c\uba74, \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0\uc11c\ub294 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uac00 \uadf8\ub807\ub2e4. \uc624\uc77c\ub0a8\uacfc \ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 \uac8c\uc784\uc758 \ubcf8\uc9c8\uc744 \uaff0\ub6ab\uace0 \uc788\uc73c\uba70 \ucc38\uac00\uc790\ub4e4\uc758 \uc2ec\ub9ac\ub97c \uc798 \uc54c\uace0 \uc788\ub2e4. \uadf8\ub807\uae30 \ub54c\ubb38\uc5d0 \uadf8\ub4e4\uc740 \uc544\uc8fc \uc990\uac81\uac8c \uac8c\uc784\uc744 \uc990\uae30\uace0, \ub9c8\uc74c\ub9cc \uba39\uc73c\uba74 \uadf8 \uac8c\uc784\uc5d0\uc11c \uc544\uc8fc \uc190\uc27d\uac8c \uc774\uae38 \uc218 \uc788\ub294 \uac83\uc774\ub2e4.\n\n\ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 \uc138\uc0c1\uc744 \ub5a0\ub098\uae30 \uc804 \ud53c\ube44\ub9b0\ub0b4 \ub098\ub294 \ud22c\uc790 \uac8c\uc784\uc5d0\uc11c \uc2b9\ub9ac\ud558\ub294 \ubc29\ubc95\uacfc \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \ube44\ubc00\uc744 \u300e\ud22c\uc790\ub294 \uc2ec\ub9ac\uac8c\uc784\uc774\ub2e4\u300f\uc5d0 \ub0a8\uaca8\ub450\uc5c8\ub2e4. \uc774 \ucc45\uc740 \uc6b0\ub9ac\ub85c \ud558\uc5ec\uae08 \ud63c\ub780\uc2a4\ub7ec\uc6b4 \uc8fc\uc2dd\uc2dc\uc7a5\uc744 \uc990\uae38 \uc218 \uc788\ub3c4\ub85d \ud574 \uc904 \ubfd0\ub9cc \uc544\ub2c8\ub77c, \uc6b0\ub9ac\ub97c \ucd5c\ud6c4\uc758 \uc2b9\uc790\ub85c \ub9cc\ub4e4\uc5b4 \ud070 \ubd80\ub97c \uc548\uaca8 \uc904 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 1\n\n**\uc774\ubc88 \ucc45 \uc5ed\uc2dc\ub3c4 \uc131\uacf5\uc744 \uc6d0\ud558\ub294 \ud22c\uc790\uc790\ub77c\uba74 \ubc18\ub4dc\uc2dc \uc77d\uc5b4\uc57c \ud558\ub294 \ucc45\uc774\ub2e4.** \uc774 \ucc45\uc740 \uc99d\uad8c\uc2dc\uc7a5\uc758 \ube44\ubc00\uc744 \ud658\uae30\uc2dc\ud0a4\uba70, \uc6b0\ub9ac\ub85c \ud558\uc5ec\uae08 \uc790\uc8fc\uc801\uc774\uace0 \ub3c5\uc790\uc801\uc778 \uc0ac\uace0\uc640 \ud589\ub3d9\uc744 \ud558\ub3c4\ub85d \uc720\ub3c4\ud55c\ub2e4. \uc774 \ucc45\uc740 \uc808\ub300 \uad50\uc7ac\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub294 \"\ub098\ub294 \uac00\ub974\uce58\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uc774\uc57c\uae30\ud560 \ubfd0\uc774\ub2e4\"\ub77c\uace0 \uc785\ubc84\ub987\ucc98\ub7fc \ub9d0\ud558\ub4ef\uc774, \ud558\ub098\uc758 \uc774\uc57c\uae30\ucc45\uc774\ub2e4. \ub3c5\uc790\ub4e4\uc774 \uc815\uc2e0\uc801 \ub9cc\uc871\uacfc \ud568\uaed8 \ubb3c\uc9c8\uc801 \uc131\uacf5\ub3c4 \ud568\uaed8 \uc5bb\uae30\ub97c \uae30\uc6d0\ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 2\n\n80\uc138\uc758 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc640 20\uc138\uc758 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uac00 \ube44\uc5d4\ub098\uc5d0\uc11c \uc5f4\ub9b0 \uc740\ud589 \uad00\ub828 \uad6d\uc81c\ud68c\uc758\uc5d0 \ud568\uaed8 \uc788\uc5c8\ub2e4. 20\uc138\uc758 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 \ud68c\uc758\uc7a5 \ud55c\uad6c\uc11d\uc5d0\uc11c \uadc0\ub97c \ucad1\uae0b \uc138\uc6b0\uace0 \uc788\uc5c8\ub2e4. \uadf8\ub294 \ub2e8 \ud55c\ub9c8\ub514\uc758 \uc815\ubcf4\ub77c\ub3c4 \uc5bb\uac8c \ub41c\ub2e4\uba74 \uadf8\uac83\uc73c\ub85c \uc7ac\uc0b0\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4\ub294 \ud655\uc2e0\uc5d0 \ucc28 \uc788\uc5c8\ub2e4.\n\n80\uc138\uc758 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uac00 \ub9d0\ud588\ub2e4.\n\n> \"\uc815\ubcf4\ub97c \uc5bb\ub294 \uac83\uc740 \uace7 \ud30c\uc0b0\ud55c\ub2e4\ub294 \uac83\uc774 \ub098\uc758 \uacbd\ud5d8\uc774\ub2e4.\"\n\n20\uc138\uac00 \ubc18\ubb38\ud588\ub2e4.\n\n> \"\uc624\ub298\ub0a0 \uc0ac\ub78c\ub4e4\uc740 \ucef4\ud4e8\ud130\uc640 \uace0\ucc28\uc6d0\uc801\uc778 \ubd84\uc11d \ubc29\ubc95\uc744 \uc0ac\uc6a9\ud558\uace0 \uc788\uc5b4. \ub10c \uadf8\uac83\ub3c4 \ubaa8\ub974\ub2c8?\"\n\n80\uc138\uac00 \ub300\ub2f5\ud588\ub2e4.\n\n> \"\uadf8\ub7f0 \ubaa8\ub4e0 \uac83\ub4e4\uc774 \uc815\ud655\ud55c \ud559\ubb38\uc774\ub77c\uace0 \ubbff\uace0 \uc788\uc9c0. \ud558\uc9c0\ub9cc \uacbd\uc81c\ud559\uc774\ub098 \uc7ac\uc815\ud559\uc740 \ud559\ubb38\uc774 \uc544\ub2c8\uc57c. \uadf8\uac83\ub4e4\uc740 \ud558\ub098\uc758 \uc608\uc220\uc774\uc57c. \uadf8\ub7ec\ub2c8 \ud68c\uc758 \uc7a5\uc18c\ub97c \ubbf8\uc220\uad00\uc73c\ub85c \uc62e\uae30\ub294 \uac8c \ub354 \ub098\uc744\uc9c0\ub3c4 \ubab0\ub77c.\"\n\n**\"\uc0ac\ub78c\ub4e4\uc740 \ub9e4\uc6b0 \ub9ce\uc740 \uac83\uc744 \uc54c\uc544\uc57c \ud574. \ud558\uc9c0\ub9cc \uadf8\uac83\ub4e4\uc740 \ucc45\uc774\ub098 \ucef4\ud4e8\ud130\uc5d0\uc11c \ucc3e\uc744 \uc218 \uc788\ub294 \uc22b\uc790\ub4e4\uc774 \uc544\ub2c8\uc57c. \uc0ac\ub78c\ub4e4\uc740 \uc0ac\uac74\ub4e4 \uac04\uc758 \uc5f0\uad00\uc131\uc744 \uc774\ud574\ud574\uc57c\ub9cc \ub274\uc2a4\ub4e4\uc744 \ud574\uc11d\ud560 \uc218 \uc788\uc5b4. \ub610\ud55c \uc601\uac10\uc744 \uac00\uc838\uc57c \ud558\uace0, \uc218\ub9ce\uc740 \ub3c5\uc11c\uc640 \uacbd\ud5d8, \uadf8\ub9ac\uace0 \ub610 \uacbd\ud5d8\uc744 \ud574\uc57c\ub9cc \ud574.\"**\n\n---\n\n## \ud3ec\uc778\ud2b8 3\n\n**\uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \uc2ec\ub9ac\ud559\uc758 \uc5ed\ud560\uc740 \uc544\ubb34\ub9ac \uac15\uc870\ud574\ub3c4 \uc9c0\ub098\uce68\uc774 \uc5c6\ub2e4. \ub2e8\uae30\uc801, \uadf8\ub9ac\uace0 \uc911\uae30\uc801\uc73c\ub85c \uc2ec\ub9ac\ud559\uc740 \uc99d\uad8c\uc2dc\uc7a5\uc758 90%\ub97c \uacb0\uc815\ud55c\ub2e4.** \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \uc2ec\ub9ac\ud559\uc740 \ub9e4\uc6b0 \uc12c\uc138\ud55c \uc190\uac00\ub77d \uac10\uac01\uc73c\ub85c \uc6b4\uc601\ub418\uc5b4\uc57c\ub9cc \ud558\ub294 \ud558\ub098\uc758 \ud559\ubb38\uc774\uba70, \uadf8\uac83\uc740 \uac70\uc758 \uc608\uc220\uc5d0 \uac00\uae5d\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 4\n\n\uc99d\uad8c\uc2dc\uc7a5\uc740 \uc624\ub298\ub0a0\uc5d0\ub3c4 \uc5ec\uc804\ud788 \ubd88\ud22c\uba85\ud558\ub2e4. \uadf8\ub7ec\ub098 \ub9cc\uc57d \uc99d\uad8c\uc2dc\uc7a5\uc774 \ud22c\uba85\ud574\uc9c4\ub2e4\uba74 \uadf8\uac83\uc740 \ub354 \uc774\uc0c1 \uc99d\uad8c\uc2dc\uc7a5\uc774 \uc544\ub2c8\ub2e4. \ud22c\uc790\uc790 \uc2a4\uc2a4\ub85c\uac00 \uc4f8\ub370\uc5c6\ub294 \uc218\ub2e8\uc73c\ub85c \ud63c\ud0c1\ud558\uac8c \ub9cc\ub4e4\uace0, \uadf8 \ud63c\ud0c1\ud55c \ubb3c\uc5d0\uc11c \ub09a\uc2dc\uc9c8\uc744 \ud55c\ub2e4. \uc5b8\ub860\uc758 \ubcf4\ub3c4\uc640 \ud574\uc124\uc740 \uc628\ud1b5 \ud63c\ub780\uc73c\ub85c \uac00\ub4dd\ud558\ub2e4.\n\n**\uadf8\ub9ac\ud558\uc5ec \ub300\uac1c\ub294 \uc8fc\uac00 \uc9c0\uc218\uac00 \uba3c\uc800 \ubcc0\ud558\uace0, \uae09\ud788 \ub9cc\ub4e4\uc5b4\ub0b8 \uc774\uc720\ub4e4\uc774 \uadf8 \ub4a4\ub97c \ub530\ub974\uac8c \ub41c\ub2e4.** \uc2e4\uc5c5\ub960\uc774 \uac10\uc18c\ud574\ub3c4 \uc99d\uad8c \uc2dc\uc138\uac00 \ud558\ub77d\ud560 \uc218 \uc788\ub2e4\uace0 \uac71\uc815\ud558\uba70, \uba70\uce60 \ub4a4\uc5d0\ub294 \uc2e4\uc5c5\ub960\uc774 \uc99d\uac00\ud574\ub3c4 \uc99d\uad8c \uc2dc\uc138\uac00 \ud558\ub77d\ud560 \uac83\uc774\ub77c\uace0 \ub9d0\ud55c\ub2e4. \uc5b4\ub5a4 \uac83\uc774 \ud638\uc7ac\ub85c \ub610\ub294 \uc545\uc7ac\ub85c \ubc18\uc601\ub420 \uac83\uc778\uc9c0 \ud22c\uc790\uc790\ub4e4\uc740 \uadf8 \uaddc\uce59\uc744 \uc804\ud600 \uc54c \uc218 \uc5c6\uae30 \ub54c\ubb38\uc5d0, \uc99d\uad8c\uc2dc\uc7a5\uc740 \uc790\uc8fc \uc220\uc8fc\uc815\ubc45\uc774\ucc98\ub7fc \ud589\ub3d9\ud55c\ub2e4. \uc989 \uc99d\uad8c\uc2dc\uc7a5\uc740 \uc5c9\ub9dd\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 5\n\n\uc8fc\uc2dd\uc758 \uc2dc\uc138\uac00 \uc624\ub974\ub77d\ub0b4\ub9ac\ub77d\ud558\uba70 \uc6c0\uc9c1\uc778\ub2e4. \uadf8 \ub4a4\uc5d0 \uc218\ub9ce\uc740 \ucc38\uc5ec\uc790\ub4e4\uc740 \uc11c\ub85c \uc815\ubc18\ub300\uc758 \uc8fc\uc7a5\uc744 \ud558\uba74\uc11c, \uc65c \uadf8\ub807\uac8c \ub418\uc5b4\uc57c\ub9cc \ud588\ub294\uac00\uc5d0 \ub300\ud574 \uc544\uc8fc \uadf8\ub7f4\ub4ef\ud55c \uc124\uba85\uc744 \ub0b4\ub193\ub294\ub2e4. **\uc2dc\uc138\uac00 \ub274\uc2a4\ub97c \ub9cc\ub4dc\ub294 \uac83\uc774\uc9c0, \ub274\uc2a4\uac00 \uc2dc\uc138\ub97c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.** \uc678\ubd80\ub85c\ubd80\ud130\uc758 \ub274\uc2a4\uac00 \uc5b8\uc81c\ub098 \uc2dc\uc138 \uc0c1\uc2b9\uc5d0 \uacb0\uc815\uc801 \uc5ed\ud560\uc744 \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 6\n\n\uc774\ub7ec\ud55c \ube44\uad00\uc8fc\uc758\ub294 \uc99d\uad8c\uc2dc\uc7a5 \ucc38\uc5ec\uc790\ub4e4\uc758 \uacf5\ud1b5\uc801\uc778 \ud2b9\uc9d5\uc774\ub2e4. \uc65c\ub0d0\ud558\uba74 \uadf8\ub4e4\uc740 \uae4a\uc774 \uc0ac\uace0\ud558\uc9c0 \uc54a\uace0 \uc678\ubd80 \uc0ac\uac74\ub4e4\uc744 \uc2ec\uc0ac\uc219\uace0\ud558\uc9c0 \uc54a\uc73c\uba70, \uadf8\uc800 \ube68\ub9ac \ub300\ubc15\uc744 \ud130\ub728\ub9ac\uace0 \uc2f6\uc5b4 \ud558\uace0 \ubb54\uac00 \uc0ac\uace0 \ud314\uace0 \uc2f6\uc5b4 \ud558\ub294 \uc131\uae09\ud55c \uc778\uac04\ub4e4\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. **\uc774\ub7f0 \uac8c\uc784\uafbc\ub4e4\uc774 \uc99d\uad8c\uc2dc\uc7a5\uc5d0 \ub9ce\uc774 \uad00\uc5ec\ud558\uba74 \ud560\uc218\ub85d \uc99d\uad8c\uc2dc\uc7a5\uc758 \ubd84\uc704\uae30\ub294 \ub354\uc6b1 \ubd88\uc548\uc815\ud574\uc9c4\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 7\n\n\ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 '\ud070 \uc190'\uacfc '\uc791\uc740 \uc190'\uc774\ub77c\ub294 \ube44\uc720\ub85c \uc8fc\uc2dd \ud22c\uc790\uc758 \uc2ec\ub9ac\ub97c \uc124\uba85\ud55c\ub2e4. \ubd84\uc11d\uac00\ub4e4\uc740 \uac70\ub798\ub7c9\uc774 \ub298\uc5b4\ub09c\ub2e4\ub294 \uac83\uc744 \uc99d\uad8c\uc2dc\uc7a5\uc774 \uc548\uc815\uc801\uc774\ub77c\ub294 \uc99d\uac70\ub77c\uace0 \ub9d0\ud55c\ub2e4. \uadf8\ub7ec\ub098 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \uc0dd\uac01\uc740 \uadfc\ubcf8\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4.\n\n**\uc2dc\uc138\uac00 \uc0c1\uc2b9\ud558\ub294 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \uac70\ub798\ub7c9\uc774 \ub298\uc5b4\ub0a0\uc218\ub85d, \ub354 \ub9ce\uc740 \uc8fc\uc2dd\uc774 \ud070 \uc190(\uc2ec\ub9ac\uc801\uc73c\ub85c \uc548\uc815\ub41c \ucc38\uc5ec\uc790)\uc5d0\uc11c \uc791\uc740 \uc190(\uc2ec\ub9ac\uc801\uc73c\ub85c \ubd88\uc548\uc815\ud55c \ucc38\uc5ec\uc790)\uc73c\ub85c \uc774\ub3d9\ud55c\ub2e4. \uadf8\ub9ac\ud558\uc5ec \ubaa8\ub4e0 \uc8fc\uc2dd\uc774 \uc791\uc740 \uc190\ub4e4 \uc18d\uc5d0 \uba38\ubb3c\ub7ec \uc788\uac8c \ub418\uba74, \uc8fc\uac00 \ud3ed\ub77d\uc740 \uace7\ubc14\ub85c \ub208\uc55e\uc5d0 \ub2e5\uccd0\uc624\uac8c \ub41c\ub2e4.** \ub300\uc911\uc758 \uc2ec\ub9ac\uc801 \ubc18\uc751\uc758 \uac15\ub3c4\ub294 \ub2e8\uc9c0 \uc2dc\uc7a5\uc758 \uc774\ub7ec\ud55c \uae30\uc220\uc801 \uc0c1\ud0dc\uc5d0 \ub2ec\ub824 \uc788\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 8\n\n\ub098\ub294 \uc2ec\uc0ac\uc219\uace0, \ub17c\ub9ac, \uc815\ud655\uc131\uc758 \uc808\ub300\uc801 \uac00\uce58\ub97c \ub454\ub2e4. \uacbd\uc81c\ud559 \uad50\uc218\ub4e4\uc740 \ub0b4 \ubc1c\ud45c \ub0b4\uc6a9\uc5d0 \uc790\uc8fc \ube44\uc6c3\ub294\ub2e4. \uadf8\ub807\ub2e4\uba74 \ub098\ub294 \uac70\uc9d3\ub9d0\uc7c1\uc774 \ub299\uc740\uc774\uc77c\uae4c? \ub300\ubd80\ubd84\uc758 \uacbd\uc81c\ud559 \uad50\uc218\ub4e4\uc740 \uac1d\uc7a5\uc5d0\uc11c \ud558\ub8e8 24\uc2dc\uac04\uc744 \uc628\uc804\ud788 \uc9c0\ub0b8 \uc801\uc774 \ub2e8 \ud55c \ubc88\ub3c4 \uc5c6\uc744 \uac83\uc774\ub2e4. **\uadf8\ub7ec\ub098 \ub098\ub294 70\ub144 \ub3d9\uc548 \uc138\uacc4 70\uac1c\uc758 \uc99d\uad8c\uc2dc\uc7a5\uc744 \ub3cc\uc544\ub2e4\ub2c8\uba70 \uc0b4\uc544\uc628 \ud22c\uc790\uc790\uc774\ub2e4.** \ub3c5\uc790 \uc5ec\ub7ec\ubd84\ub4e4\uc740 \uc774 \ucc45\uc744 \ud1b5\ud574 \ucee4\ub2e4\ub780 \uc2ec\ub9ac\uac8c\uc784\uc778 \uc99d\uad8c\uc2dc\uc7a5\uc744 \ub4e4\uc5ec\ub2e4\ubcfc \uc218 \uc788\uac8c \ub420 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 9\n\n\ub3c8\uc774 \ubaa8\ub4e0 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ub3c8\uc774 \ub9ce\uc740 \uac83\uc774 \uc88b\ub2e4. \uc5b4\ub5a4 \ubd80\uc790\ub294 \uc544\ub984\ub2e4\uc6b4 \uac83\uacfc \ube44\uc2fc \uac83\ub4e4\uc744 \uc5bc\ub9c8\ub4e0\uc9c0 \uc0b4 \uc218 \uc788\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uadf8\uac83\ub4e4\uc744 \uc0ac\uc9c0 \uc54a\ub294\ub2e4. \uc65c\ub0d0\ud558\uba74 \uadf8\uac83\ub4e4\uc744 \uc0b4 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub9cc\uc871\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub4e4\uc740 \ub3c8\uc758 \ube5b\uc744 \ub290\ub080\ub2e4. \uadf8\uac83\ub9cc\uc73c\ub85c\ub3c4 \uadf8\ub4e4\uc740 \uc871\ud558\ub2e4.\n\n\ud55c\ud3b8\uc73c\ub85c \ub3c8\uc740 \uc704\ud5d8\ud558\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc740 \ud604\uae08\uc744 \ub9cc\uc9c8 \ub54c\uba74 \uc5b8\uc81c\ub098 \uc131\uc801 \uc695\uad6c\ub97c \ub290\ub080\ub2e4\uace0 \uace0\ubc31\ud560 \uc815\ub3c4\uc600\ub2e4. **\ub3c8\uc740 \uc778\uac04\uc744 \ud0c0\ub77d\uc2dc\ud0ac \uc218\ub3c4 \uc788\uace0, \ub610\ud55c \uc778\uac04\uc758 \ucd94\ud55c \uc131\uc9c8\uc744 \ubc1d\uc740 \uacf3\uc73c\ub85c \ub04c\uc5b4\ub0bc \uc218\ub3c4 \uc788\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 10\n\n\uc0ac\ub78c\ub4e4\uc774 \ud30c\ub77c\ub2e4\uc774\uc2a4\ub85c \ud1b5\ud558\ub294 \ubb38\uc758 \uc5f4\uc1e0\uc778 \ub3c8\uc744 \uac16\uc9c0 \ubabb\ud558\uba74, \ud30c\ub77c\ub2e4\uc774\uc2a4\ub97c \uc9c0\ucc99\uc5d0 \ub450\uace0\ub3c4 \ub3c4\ub2ec\ud558\uc9c0 \ubabb\ud55c \ucc44 \uc8fc\ubcc0\uc744 \ub9f4\ub3cc\uc544\uc57c \ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub098\ub294 \uae68\ub2eb\uac8c \ub418\uc5c8\ub2e4. \uadf8\ub798\uc11c \ub098\ub294 \uacb0\uc2ec\ud588\ub2e4. \ub3c8\uc744 \ubc8c\uc790, \uadf8\uac83\ub3c4 \uc544\uc8fc \ub9ce\uc740 \ub3c8\uc744.\n\n\ub098\ub294 \ub3c8\uc744 \uc22d\ubc30\ud558\uae30 \uc2dc\uc791\ud588\uc73c\uba70 \ub3c8\uc744 \ub298\ub9ac\ub294 \uac83\uc744 \uc778\uc0dd\uc758 \uc720\uc77c\ud55c \ubaa9\ud45c\ub85c \uc0bc\uae30 \uc2dc\uc791\ud588\ub2e4. \uc774\ub807\uac8c \ub418\uc790 \ub0b4 \uc0b6\uc758 \ubaa8\ub4e0 \uac00\uce58\uc640 \uc785\uc7a5\uc774 \ubcc0\ud558\uac8c \ub418\uc5c8\ub2e4. \ub3c8 \uc774\uc678\uc758 \uac83\ub4e4\uc774 \ud558\ucc2e\uac8c \ubcf4\uc600\ub2e4. \uadf8\ub9ac\uace0 \ub098\ub294 \uc5b8\uc81c \uc5b4\ub514\uc11c\ub098 \ub3c8\uc744 \ubc8c \uc218 \uc788\uc5c8\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 11\n\n\ud22c\uc790 \ucd08\ucc3d\uae30 \ub0b4\uac00 \ubcf8 \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \ub9c8\uce58 \ucee4\ub2e4\ub780 \uce74\uc9c0\ub178\uc640 \uac19\uc558\ub2e4. \ub3c8\uc740 \uacf5\uc911\uc5d0 \uac78\ub824 \uc788\uc5c8\ub2e4. \uc774\uac83\uc744 \ub290\ub07c\uace0 \ubd99\uc7a1\uae30 \uc704\ud574\uc11c\ub294 \uc548\ud14c\ub098\uac00 \ud544\uc694\ud588\ub2e4. **\ud558\uc9c0\ub9cc \uadf8\uac83\uc740 \uadf8\ub9ac \uc5b4\ub824\uc6b4 \uc77c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ucda9\ubd84\ud788 \uc2ec\uc0ac\uc219\uace0\ud558\uae30\ub9cc \ud558\uba74 \ub418\ub294 \uc77c\uc774\uc5c8\uc73c\ub2c8 \ub9d0\uc774\ub2e4.**\n\n\uadf8\ub7ec\ub098 \uadf8 \uce74\uc9c0\ub178\uc5d0\uc11c\ub294 \ub204\uad6c\ub098 \uc790\uc2e0\ub9cc\uc774 \ucd5c\uace0\uc758 \uc815\ubcf4\ub97c \uc54c\uace0 \uc788\ub2e4\uace0 \uc8fc\uc7a5\ud588\ub2e4. \ub098\uc774\ub294 \uc5b4\ub838\uc9c0\ub9cc, \uc774\uacf3\uc758 \ud5c8\ud48d\uc7c1\uc774\ub4e4\uacfc \ubc18\ub300\ub85c \ud589\ub3d9\ud558\uba74 \ub420 \uac83 \uac19\ub2e4\ub294 \uc0dd\uac01\uc744 \ud588\ub2e4. \ub098\ub294 \uc57d\uc138\uc7a5 \ud22c\uc790\ub97c \uc2dc\uc791\ud588\ub2e4. \ubb3c\ub860 \uac70\uae30\uc5d0\ub294 \ub098\uc758 \uc9c0\uc801 \uc624\ub9cc\ub3c4 \uac1c\uc785\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc6b0\uc5f0\ud788\ub3c4 \ub098\ub294 \uc774\ub97c \ud1b5\ud574 \uc131\uacf5\uc744 \uac70\ub450\uc5c8\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 12\n\n**\ubc14\ub78c\uc9c1\ud55c \ud22c\uc790\uc790\ub77c\uba74 \uc5b8\uc81c\ub098 \uc790\uc720\ub85c\uc6cc\uc57c \ud558\uba70, \ub300\uc911\uc758 \uc2ec\ub9ac\uc801 \ubd84\uc704\uae30\uc5d0 \uac10\uc5fc\ub418\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4.** \ub0b4\uac00 \ud22c\uc790\ud55c \uc885\ubaa9\ub4e4\uc758 \uc2dc\uc138\uac00 \ubd88\ub9ac\ud558\uac8c \uc804\uac1c\ub420 \ub54c \ub098\ub294 \uacb0\ucf54 \ub3d9\uc694\ud558\uc9c0 \uc54a\uc73c\uba70 \uadf8 \uc8fc\uc2dd\uc5d0 \ub300\ud55c \uc5b4\ub5a0\ud55c \uc815\ubcf4\ub3c4 \ub4e4\uc73c\ub824 \ud558\uc9c0 \uc54a\ub294\ub2e4. \ud558\uc9c0\ub9cc \uc678\uad50, \uc870\uc138, \uae08\uc735\uc815\ucc45, \ubb34\uc5ed\uacfc \uad00\ub828\ub41c \ub274\uc2a4\ub4e4\uc5d0 \ub300\ud574\uc11c\ub294 \uc790\uc138\ud788 \uad00\ucc30\ud55c\ub2e4. \uc8fc\uc2dd \uc2dc\uc138\uac00 \ud56d\uc0c1 \ub17c\ub9ac\uc801\uc778 \uac83\uc740 \uc544\ub2c8\uba70 \uc8fc\ubcc0 \ud604\uc0c1\uc744 \uc5b8\uc81c\ub098 \uadf8\ub300\ub85c \ubc18\uc601\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ubbc0\ub85c, \uc99d\uad8c\uc2dc\uc7a5\uc758 \ubc18\uc751\uc744 \ub2e8\uae30\uc801\uc73c\ub85c\ub294 \uc608\uce21\ud560 \uc218 \uc5c6\uc9c0\ub9cc \uc7a5\uae30\uc801\uc73c\ub85c \uc608\uce21\ud558\ub294 \uac83\uc740 \uc5b4\ub290 \uc815\ub3c4 \uac00\ub2a5\ud558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 13\n\n**\ud22c\uc790\ub294 \uc808\ub300 \ube5a\uc73c\ub85c \ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc65c\ub0d0\ud558\uba74 \ube5a\uc744 \uc9c0\uc9c0 \uc54a\ub294 \uc0ac\ub78c\ub9cc\uc774 \uc790\uc2e0\uc758 \uc0dd\uac01\uc5d0 \uc628\uc804\ud788 \ub530\ub97c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 14\n\n> \"\uc99d\uad8c\uc2dc\uc7a5\uc740 \uc628\ud1b5 \uc815\uc2e0\ubcd1\uc790\ub4e4\ub85c \ub4a4\ub36e\uc5ec \uc788\ub2e4.\" \u2014 \uc804 \ub3c5\uc77c \uc218\uc0c1 \ud5ec\ubb34\ud2b8 \uc288\ubbf8\ud2b8\n\n\ub098\ub294 \uc774 \ub9d0\ub9cc\ud07c\uc740 \ub2f9\uc2dc\uc758 \uc99d\uad8c\uc2dc\uc7a5\uc744 \ud655\uc2e4\ud558\uace0 \uc801\uc808\ud558\uac8c \ud45c\ud604\ud588\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \ub300\uc911 \uc2ec\ub9ac\ud559\uc758 \uace0\uc804\uc801 \uc800\uc11c\uc5d0\uc11c \"\ub300\uc911\uc740 \uc54c\uc9c0 \ubabb\ud55c\ub2e4\"\uace0 \uae30\uc220\ud588\ub2e4. \ub300\uc911\uc774 \uc601\ub9ac\ud558\uace0 \uc0dd\uac01\ud558\ub294 \uc778\uac04\ub4e4\ub85c \uad6c\uc131\ub418\uc5b4 \uc788\ub2e4\uba74 \uc774\ub7ec\ud55c \ud2b9\uc9d5\uc740 \ub354 \uc798 \uc801\uc6a9\ub41c\ub2e4. **\ub9cc\uc57d \ucc9c\uc7ac\uc5d0 \uac00\uae4c\uc6b4 100\uba85\uc758 \uc778\uac04\ub4e4\uc744 \uc881\uc740 \ud55c \uacf5\uac04\uc5d0 \ubab0\uc544 \ub123\ub294\ub2e4\uba74, \uc774\ub4e4\uc740 \uc815\uc2e0\uc774 \uc544\ub2c8\ub77c \uac10\uc815\uc5d0 \uc758\ud574 \uc9c0\ubc30\ub41c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 15\n\n\ud55c \uc99d\uad8c\uc2dc\uc7a5 \uc804\ubb38\uac00\uac00 \ucda9\ubd84\ud55c \uc2ec\uc0ac\uc219\uace0\ub97c \uac70\uccd0 \uc790\uc2e0\uc774 \ubcf4\uc720\ud55c \uc8fc\uc2dd\uc744 \ubaa8\ub450 \ud314\uae30\ub85c \uacb0\uc815\ud588\ub2e4\uace0 \uce58\uc790. \uac1d\uc7a5\uc73c\ub85c \ub098\uac04 \uadf8\ub294 \ub9e4\uc6b0 \ub099\uad00\uc801\uc778 \ubd84\uc704\uae30\uac00 \uc9c0\ubc30\ud558\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \ub290\ub080\ub2e4. \uadf8\ub9ac\uace0 \uba87 \ucd08 \ub4a4 \uadf8\ub294 \uc870\uae08 \uc804\uae4c\uc9c0\uc758 \uacb0\uc815\uc744 \ubc14\uafb8\uc5b4, \uc790\uc2e0\uc758 \uc8fc\uc2dd\uc744 \ud30c\ub294 \ub300\uc2e0 \uc0c8\ub85c\uc6b4 \uc8fc\uc2dd\uc744 \ub354 \uc0ac\uac8c \ub41c\ub2e4.\n\n**\uc218\uc2ed\ub9cc, \uc5b4\uca4c\uba74 \uc218\ubc31\ub9cc \uba85\uc758 \uc774\ub4e4 \ubcc0\ub355\uc7c1\uc774\ub4e4\uc758 \ub4a4\ub97c \ub530\ub77c \ubaa8\ub4e0 \uac70\ub798\ub97c \uc798\ubabb \ud310\ub2e8\ud558\ub294 \uc2e4\uc218\ub97c \uc800\uc9c0\ub978\ub2e4.** \ub9cc\uc57d \uc2dc\uc138\uac00 \uc0c1\uc2b9\ud558\uac8c \ub418\uba74 \uac1c\ubbf8\ub4e4\uc740 \ub5a0\ub098\ub294 \uae30\ucc28\uc5d0 \ube68\ub9ac \ub6f0\uc5b4\uc624\ub974\uae30 \uc704\ud574 \uc544\ubb34 \uc0dd\uac01 \uc5c6\uc774 \uc8fc\uc2dd\uc744 \ub9e4\uc785\ud55c\ub2e4. \uc774\ub7f0 \uc2ec\ub9ac\uc801 \uba54\ucee4\ub2c8\uc998\uc744 \uc54c\uc544\ucc28\ub9b0\ub2e4\uba74, \uc9c0\uae08\uae4c\uc9c0 \ubb34\uc758\uc2dd\uc801\uc73c\ub85c \ub9e4\uc218 \ubc84\ud2bc\uc744 \ub20c\ub800\ub358 \uc790\uc2e0\uc758 \ud589\ub3d9\uc5d0\uc11c \uc18c\ub984\uc774 \ub3cb\uc744\uc9c0\ub3c4 \ubaa8\ub974\uaca0\ub2e4.\n\n\ub9cc\uc57d \ub2f9\uc2e0\uc774 \uac15\uc138\uc7a5 \ud22c\uc790\uc790\ub77c\uba74, \uc774\ub7f0 \ubcc0\ub355\uc7c1\uc774\ub4e4\uc758 \ud589\ub3d9\uc744 \ud56d\uc0c1 \uc8fc\uc758 \uae4a\uac8c \uad00\ucc30\ud574\uc57c \ud55c\ub2e4. \uc774\ub7f0 \ubcc0\ub355\uc7c1\uc774\ub4e4 \uc911 \uc774\ub7f0 \ub0b4\ub9c9\uc744 \uc54c\uace0 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc744 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 '\uc2dc\uc138 \ubd80\uc591\uc790'\ub77c\uace0 \ubd80\ub978\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 16\n\n\ub2e8\uae30\uc801\uc73c\ub85c \uacbd\uc81c \uc0c1\ud669\uc740 \uc99d\uad8c \uc2dc\uc138\uc5d0 \uc5b4\ub5a0\ud55c \uc601\ud5a5\ub3c4 \uc8fc\uc9c0 \ubabb\ud55c\ub2e4. \uae08\ub9ac\uc640 \uacbd\uae30 \ub4f1 \uacbd\uc81c \uc0c1\ud669\uc774 \uc2dc\uc138\uc5d0 \ubbf8\uce58\ub294 \uacbd\uc6b0\ub294 \uba87\uba87 \ud22c\uc790\uc790\ub4e4\uc774 \uba3c \ubbf8\ub798\ub97c \ubc14\ub77c\ubcf4\uace0 \ud589\ub3d9\ud560 \ub54c \ubfd0\uc774\ub2e4. **\uc99d\uc2dc \uc8fc\ubcc0\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uc0ac\uac74\ub4e4\uc774 \uc99d\uc2dc\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc0ac\uac74\uc5d0 \ub300\ud55c \ud22c\uc790\uc790\ub4e4\uc758 \ubc18\uc751\uc774 \uc99d\uc2dc\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4.**\n\n\uadf8\ub798\uc11c \ub2e8\uae30\uc801\uc73c\ub85c\ub294 \uc2ec\ub9ac\ud559\uc774 \uc99d\uad8c\uc2dc\uc7a5\uc758 90%\ub97c \uacb0\uc815\ud55c\ub2e4. \uc2ec\ub9ac\ud559 \uc678\uc5d0 \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc911\uae30\uc801 \ucd94\uc138\uc5d0 \ub300\ud55c \uacb0\uc815\uc801 \uc694\uc18c\ub294 \uae08\ub9ac\ub2e4. \uae08\ub9ac\ub294 \uc77c\ucc28\uc801\uc73c\ub85c \ucc44\uad8c \uc2dc\uc7a5\uc5d0 \uc9c1\uc811\uc801\uc778 \uc601\ud5a5\uc744 \uc900\ub2e4. \ucc44\uad8c \uc2dc\uc7a5\uc5d0 \ub3c8\uc774 \ubab0\ub9ac\uace0 \ub098\uc11c\uc57c \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \ub3c8\uc774 \ube60\uc9c0\uae30 \uc2dc\uc791\ud558\uace0 \uc8fc\uac00\ub294 \ube44\ub85c\uc18c \ub5a8\uc5b4\uc9c0\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc989 \uae08\ub9ac \ud6a8\uacfc\ub294 \uc77c\uc815 \uc2dc\uac04\uc774 \uc9c0\ub09c \ub4a4\uc5d0 \ube44\ub85c\uc18c \ub290\ub084 \uc218 \uc788\uac8c \ub41c\ub2e4. \uadf8\ub798\uc11c \uae08\ub9ac\ub294 \uc911\uae30\uc801\uc73c\ub85c \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 17\n\n\uc7a5\uae30\uc801 \ucd94\uc138\ub97c \ub193\uace0 \ubcfc \ub54c \uc2ec\ub9ac\ud559\uc740 \ub354 \uc774\uc0c1 \uadfc\ubcf8\uc801\uc778 \uc694\uc18c\uac00 \ub418\uc9c0 \ubabb\ud55c\ub2e4. IBM, \ubca4\uce20 \ub4f1\uc758 \uae30\uc5c5\ub4e4\uc774 \uc9c0\uae08\uc758 \uc8fc\uac00\ub97c \ud615\uc131\ud560 \uc218 \uc788\uc5c8\ub358 \uc774\uc720\ub294 \uae30\ubcf8\uc801\uc778 \uc131\uacf5 \uc694\uc778\ub4e4\uc744 \uac16\ucd94\uace0 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\ub4e4 \uae30\uc5c5\ub4e4\uc758 \uc8fc\uac00\ub97c \uadf8\ub807\uac8c \ub192\uc778 \uac83\uc740 \uacb0\ucf54 \uc2ec\ub9ac\ud559\uc774 \uc544\ub2c8\ub2e4.\n\n**\ub530\ub77c\uc11c \uc0b0\uc5c5 \ubd80\ubb38\uc758 \ubc1c\uc804\uc744 \uba87 \ub144 \uc55e\ub2f9\uaca8 \ubcfc \uc218 \uc788\ub294 \uc548\ubaa9\uc744 \uac16\uace0 \uc788\ub294 \uc0ac\ub78c\uc740 \ud070\ub3c8\uc744 \ubc8c \uc218 \uc788\ub2e4.** \ub0b4 \uacac\ud574\ub85c\ub294 \ub2e4\uc74c\uc758 \ub450 \uac00\uc9c0 \uae30\ubcf8 \uc694\uc18c\ub4e4\uc774 \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc2dc\uc138\ub97c \uacb0\uc815\uc9d3\ub294\ub2e4.\n\n- **\uccab \ubc88\uc9f8: \ub3c8** (\ud1b5\ud654\ub7c9\uacfc \uc2e0\uc8fc \ubc1c\ud589\uc744 \ud1b5\ud574)\n- **\ub450 \ubc88\uc9f8: \uc2ec\ub9ac** (\ub099\uad00\uc8fc\uc758 \ub300 \ube44\uad00\uc8fc\uc758, \ubbf8\ub798\uc5d0 \ub300\ud55c \uc608\uce21)\n\n\ubaa8\ub4e0 \uc0ac\uac74\ub4e4, \ubaa8\ub4e0 \uc815\uce58\uc801\u00b7\uacbd\uc81c\uc801\u00b7\uae08\uc735\uc801 \uc218\ub2e8\ub4e4\uc774 \uc758\ubbf8\uac00 \uc788\ub4e0 \uc5c6\ub4e0, \uacb0\uad6d \uadf8\uac83\ub4e4\uc740 \uc774 \ub450 \uac00\uc9c0 \uc0ac\uc2e4\uc5d0 \uadc0\uacb0\ub41c\ub2e4.\n\n> \"\uc2dc\uc138\ub294 \ub3c8 + \uc2ec\ub9ac\ub2e4.\" \u2014 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \uacf5\uc2dd\n\n---\n\n## \ud3ec\uc778\ud2b8 18\n\n'\ub3c8'\uc774\ub77c\ub294 \uc694\uc18c\ub294 \uc7a5\uae30\uc801 \uae08\ub9ac\uc5d0 \ub2ec\ub824 \uc788\ub2e4. \uae08\ub9ac\uac00 \ub192\uc544\uc9c0\uba74 \uc8fc\uc2dd\uc744 \uc0b4 \uc218 \uc788\ub294 \ub3c8\uc774 \ubd80\uc871\ud574\uc9c4\ub2e4. \uae08\ub9ac\uac00 \ub0ae\uc544\uc9c0\uba74 \uc8fc\uc2dd\uc744 \uc0b4 \uc218 \uc788\ub294 \ub3c8\uc774 \ub9ce\uc544\uc9c4\ub2e4.\n\n\uc774\uc640 \ub2ec\ub9ac '\uc2ec\ub9ac'\ub77c\ub294 \uc694\uc18c\ub294 \uc218\ub9ce\uc740 \ubd80\ucc28\uc801 \uc694\uc18c\ub4e4\uc758 \uc0b0\ubb3c\uc774\ub2e4. \ud68c\uc0ac\uc758 \ubc30\ub2f9\uae08\uc774 \uc904\uc5b4\ub4e4\uace0 \uc138\uae08\uc774 \ub298\uc5b4\ub0ac\ub2e4\uba74 \uadf8 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc744 \ub9e4\uc218\ud558\ub294 \ub370 \uc18c\uadf9\uc801\uc774 \ub420 \uac83\uc774\ub2e4. **\uadf8\ub7ec\ub098 \ub300\uc911\uc774 \ubbf8\ub798\ub97c \ub099\uad00\uc801\uc73c\ub85c \ud3c9\uac00\ud55c\ub2e4\uba74 \uadf8\ub7ec\ud55c \uc545\uc7ac \uc18d\uc5d0\uc11c\ub3c4 \ub9e4\uc218\ub97c \ud558\uac8c \ub420 \uac83\uc774\ub2e4.** \uc65c\ub0d0\ud558\uba74 \ub099\uad00\uc8fc\uc758\uc790\ub294 \uadf8 \uc545\uc7ac\ub4e4\uc774 \ub2e8\uae30\uc801\uc73c\ub85c\ub9cc \uc601\ud5a5\uc744 \ub07c\uce60 \uac83\uc774\ub77c\uace0 \ud655\uc2e0\ud558\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n\uc9c0\uad6c\ucd0c\uc5d0\uc11c \ubc8c\uc5b4\uc9c0\ub294 \uc804\uc7c1\uacfc \ud3c9\ud654\uac00 \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc2dc\uc138\ub97c \uacb0\uc815\ud558\ub294 \uc808\ub300\uc801\uc778 \uc694\uc18c\uac00 \uc544\ub2c8\ub77c, **\uc774\uc5d0 \ub300\ud55c \ub300\uc911\uc758 \uc2ec\ub9ac\uc801 \ubc18\uc751\uc774 \ub354 \uacb0\uc815\uc801\uc778 \uc5ed\ud560\uc744 \ud55c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 19\n\nPER\uc744 \uad6c\uad6c\ub2e8\ucc98\ub7fc \uc678\uc6e0\ub2e4\uba74 \ub098\ub294 \uc808\ub300\ub85c \ub300\ubc15 \uc8fc\uc2dd\uc744 \ub9e4\uc218\ud558\uc9c0 \ubabb\ud588\uc744 \uac83\uc774\ub2e4. PER\uc774 \ub192\uc740 \uac12\uc744 \ubcf4\uc774\uba74 \uace0\ud3c9\uac00\ub77c\uace0 \ub9d0\ud55c\ub2e4\uba74 \uadf8\uac83\uc740 \uc0c1\ub2f9\ud788 \uacbd\uc9c1\ub418\uace0 \uc77c\ubc29\uc801\uc778 \uacac\ud574\uc774\ub2e4.\n\n**PER\uc744 \uad6c\uad6c\ub2e8\ucc98\ub7fc \uc678\ub294 \uc0ac\ub78c\uc740 \uc808\ub300 \uc801\uc790\ub97c \ubcf4\ub294 \ud68c\uc0ac\uc5d0 \ud22c\uc790\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud558\uc9c0\ub9cc \ub098\ub294 \uadf8\ub7f0 \ud68c\uc0ac\uc5d0 \uac00\uc7a5 \ub9ce\uc740 \ud765\ubbf8\ub97c \ub290\ub080\ub2e4.** \uc801\uc790 \uc0c1\ud0dc\uc77c \ub54c \uc8fc\uc2dd\uc744 \uc0c0\ub294\ub370 \uadf8 \ud68c\uc0ac\uac00 \ud68c\ubcf5\uc138\uc5d0 \ub4e4\uc5b4\uc11c\uac8c \ub418\uba74 \uc2dc\uc138\ub294 \uae09\uaca9\ud788 \uc0c1\uc2b9\ud558\uac8c \ub41c\ub2e4.\n\n1980\ub144\ub300 \ucd08\ubc18 \uc57d\uc138\uc7a5\uc5d0\uc11c\uc758 \ud06c\ub77c\uc774\uc2ac\ub7ec\uac00 \uadf8\ub7ac\ub2e4. \ubbf8\uad6d \uc815\ubd80\uac00 \uc804\ud1b5\uc801\uc778 \uae30\uc5c5\uc778 \ud06c\ub77c\uc774\uc2ac\ub7ec\ub97c \ud30c\uc0b0\ud558\ub3c4\ub85d \ubc29\uce58\ud558\uc9c0 \uc54a\uc744 \uac83\uc774\ub77c\uace0 \ud655\uc2e0\ud588\ub2e4. \uacbd\uae30 \ud68c\ubcf5\uacfc \uc790\ub3d9\ucc28 \uc218\uc694\uc5d0\uc11c \uc5c4\uccad\ub09c \ubc18\ub4f1\uc774 \uc788\uc744 \uac83\uc774\ub77c\uace0 \uacc4\uc0b0\ud588\ub2e4. \ub354\uc6b1\uc774 \ub098\ub294 \uadf8 \ud68c\uc0ac\uc758 \uc0c8\ub85c\uc6b4 \ucd1d\uc218 \uc544\uc774\uc544\ucf54\uce74\ub97c \ubbff\uc5c8\ub2e4. \uacb0\ub860\uc801\uc73c\ub85c 5\ub2ec\ub7ec\uc5d0 \uc0c0\ub358 \ud06c\ub77c\uc774\uc2ac\ub7ec \uc8fc\uc2dd\uc744 \ub098\ub294 105\ub2ec\ub7ec\uc5d0 \ud314\uc558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 20\n\n\ub0b4 \uc0dd\uac01\uc5d0 \uc758\ud558\uba74 \uc0ac\ub78c\ub4e4\uc740 \uc218\ud559\uc801 \uc9c0\uc2dd\uc744 \uac00\uc9c0\uace0\ub294 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \uc808\ub300 \uc774\ub4dd\uc744 \ubcfc \uc218 \uc5c6\ub2e4. \uc218\uce58\ub85c\ub294 \uacb0\ucf54 \uc2dc\uc138\ub97c \uc7b4 \uc218 \uc5c6\uc73c\uba70, \uc218\ud559\uc801 \uacc4\uc0b0\uc73c\ub85c \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc804\ub9dd\uc744 \ubbf8\ub9ac \ub9d0\ud560 \uc218 \uc5c6\ub2e4.\n\n\ubc30\ub2f9\uae08\uc744 \ub298\ub9ac\uba74 \uc8fc\uac00\ub294 \uc62c\ub77c\uac00\uc57c \ud55c\ub2e4. \ub17c\ub9ac\uc801\uc73c\ub85c \ubcf4\uba74 \uadf8\ub807\ub2e4. \ud558\uc9c0\ub9cc \ubc30\ub2f9\uae08\uc744 \ub298\ub838\uc74c\uc5d0\ub3c4 \uc8fc\uac00\ub294 \ub5a8\uc5b4\uc9c4\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ud63c\ub780\uc2a4\ub7fd\ub2e4. \ud63c\ub780\uc2a4\ub7ec\uc6b4 \uc774\uc720\ub294 \ub17c\ub9ac\uc801 \uc774\uc720\uc5d0\ub9cc \ucd08\uc810\uc744 \ub9de\ucd94\uace0 \uadfc\ubcf8\uc801\uc778 \uc774\uc720\ub97c \uac04\uacfc\ud558\uc600\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\uac83\uc740 \ubc14\ub85c **\uc218\uc694\uc640 \uacf5\uae09\uc758 \ubc95\uce59**\uc774\ub2e4.\n\n> \ub0b4\uac00 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \uc720\uc77c\ud558\uac8c \uc0ac\uc6a9\ud558\ub294 \uc218\ud559\uc774 \ubc14\ub85c \uc218\uc694\uc640 \uacf5\uae09\uc774\ub2e4.\n\n\ubc30\ub2f9\uae08\uc744 \uc544\ubb34\ub9ac \ub298\ub824\ub3c4 \uadf8 \uc8fc\uc2dd\uc744 \uc0b4 \uc0ac\ub78c\uc774 \uc5c6\ub2e4\uba74 \uc8fc\uac00\ub294 \uc624\ub974\uc9c0 \uc54a\ub294\ub2e4. \ud56d\uc0c1 \uc0dd\uac01\ud558\ub77c: \uc8fc\uc2dd\uc744 \uc0b4 \uc758\ud5a5\uc774 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub9ce\uc740\uc9c0, \uc544\ub2c8\uba74 \uc8fc\uc2dd\uc744 \ud314 \uc758\ud5a5\uc774 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub9ce\uc740\uc9c0.\n\n---\n\n## \ud3ec\uc778\ud2b8 21\n\n**\ud329\ud140 \ucf64\ud50c\ub9ac(Factum Compli) \ud604\uc0c1**: \uc5b4\ub5a4 \uc8fc\uc2dd\uc758 \uc8fc\uac00\uac00 \ud22c\uc790\uc790\ub4e4\uc774 \uc608\uc0c1\ud588\ub358 \ucd5c\ub300\uce58\uae4c\uc9c0 \uc0c1\uc2b9\ud588\ub2e4\uace0 \uac00\uc815\ud574 \ubcf4\uc790. \uadf8\uac83\uc740 \uace7 \uc8fc\uac00\uac00 \uc704\ud5d8 \uc218\uc704\uc5d0 \ub3c4\ub2ec\ud588\ub2e4\ub294 \ub73b\uc774\ub2e4. \uadf8 \uc21c\uac04\ubd80\ud130 \uadf8 \uc8fc\uc2dd\uc744 \uc0ac\ub824\ub294 \uc0ac\ub78c\uc740 \uc801\uc740 \ubc18\uba74\uc5d0, \uc774\ub4dd\uc744 \ubcf4\uae30 \uc704\ud574 \ud314\ub824\uace0 \uc2dc\ub3c4\ud558\ub294 \uc0ac\ub78c\ub4e4\uc740 \uc544\uc8fc \ub9ce\ub2e4.\n\n\uc0ac\ub78c\ub4e4\uc758 \uc0dd\uac01\uc740 \ub300\uccb4\ub85c \ube44\uc2b7\ud558\ubbc0\ub85c, \uc774\ub4e4\uc740 \ub192\uc740 \uac00\uaca9 \uc218\uc900\uc5d0 \uc774\ub974\uc790 \ub2e4 \uac19\uc774 \ud574\ub2f9 \uc8fc\uc2dd\uc744 \ud310\ub2e4. \uadf8\ub9ac\uace0 \uc8fc\uac00\ub294 \uae09\ub77d\ud55c\ub2e4. \uc989 **\uae0d\uc815\uc801 \uc804\ub9dd\uc774 \uac00\ub4dd \ucc2c \uacbd\uc6b0, \uadf8 \uc804\ub9dd\uc774 \uc774\ubbf8 \uac00\uaca9\uc5d0 \ubc18\uc601\ub418\uc5b4 \uc788\uae30 \ub54c\ubb38\uc5d0 \uadf8 \uc804\ub9dd\uc774 \ud604\uc2e4\ud654\ub418\uc5c8\uc744 \ub54c \uc624\ud788\ub824 \uc8fc\uac00\ub294 \ud558\ub77d\ud560 \uc218 \uc788\ub2e4.**\n\n\ubc18\ub300\uc758 \uacbd\uc6b0\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\ub2e4. \uae09\ubc15\ud55c \uc7ac\uc815 \ubb38\uc81c\ub85c \uc5b4\ub824\uc6c0\uc5d0 \ucc98\ud55c \uc5b4\ub5a4 \ud68c\uc0ac\uc758 \uc8fc\uac00\uac00 \ud558\ub77d\ud558\uace0 \ud558\ub77d\ud558\uc5ec \ucd5c\uc800\uce58\uc5d0 \ub2ec\ud588\uc74c\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0, \uc8fc\uac00\ub294 \ub354 \uc774\uc0c1 \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \uc624\ud788\ub824 \uc870\uae08 \ub192\uc740 \uc2dc\uc138\uc5d0 \uba38\ubb3c\ub7ec \uc788\uc5c8\ub2e4. **\ubd80\uc815\uc801 \uc804\ub9dd\uc774 \uac00\ub4dd\ud55c \uacbd\uc6b0, \uadf8 \uc804\ub9dd\uc774 \uc774\ubbf8 \uac00\uaca9\uc5d0 \ubc18\uc601\ub418\uc5b4 \uc788\uae30 \ub54c\ubb38\uc5d0 \uadf8 \uc804\ub9dd\uc774 \ud604\uc2e4\ud654\ub418\uc5c8\uc744 \ub54c \uc624\ud788\ub824 \uc8fc\uac00\ub294 \uc0c1\uc2b9\ud560 \uc218 \uc788\ub2e4.**\n\n\ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 \uc804\uc7c1\uc758 \uc704\ud5d8\uc744 \ub290\ub080 \ud22c\uc790\uc790\ub4e4\uc774 \ud63c\ube44\ubc31\uc0b0\ud558\uc5ec \uc8fc\uac00\uac00 \ud3ed\ub77d\ud588\ub294\ub370, \uc815\uc791 \uc120\uc804\ud3ec\uace0 \ub2f9\uc77c\uc5d0\ub294 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uae30\ub300\uc640\ub294 \ub2ec\ub9ac \uc2dc\uc138\uac00 \uc0c1\uc2b9\ud588\ub358 \uc801\ub3c4 \uc788\ub2e4\uace0 \ub9d0\ud55c\ub2e4.\n\n> \"\ub2f9\uc2dc \ub098\ub294 \uc2a4\uc2a4\ub85c \uae08\uc735 \ub300\ub780\uc5d0 \ub300\ube44\ud558\uace0 \uc788\uc5c8\uc9c0. \ub098\ub294 \ubaa8\ub4e0 \uc740\ud589\ub4e4\uc774 \ubb38\uc744 \ub2eb\uc744 \uac83\uc774\uba70 \uc99d\uad8c\uc2dc\uc7a5\ub3c4 \uc815\uc0c1 \uac70\ub798\uac00 \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc744 \uac83\uc774\ub77c\uace0 \uad73\uac8c \ubbff\uc5c8\uc5b4. \uadf8\ub9ac\uace0 \uc804\uc7c1\uc774 \ud130\uc9c0\uc790 \ub098\ub294 \ub108\ubb34 \uc815\uc2e0\uc774 \uc5c6\uc5b4\uc11c \uc804\ud654\ubc88\ud638\uc870\ucc28 \uae30\uc5b5\ud574\ub0bc \uc218 \uc5c6\uc5c8\uc5b4. \uadf8\ub7f0\ub370 \uae38\uac70\ub9ac\ub97c \ub098\uc130\uc744 \ub54c \ub098\ub294 \ub9e4\uc6b0 \ub180\ub77c\uc9c0 \uc54a\uc744 \uc218 \uc5c6\uc5c8\uc5b4. \uc740\ud589\ub4e4\uc740 \ubaa8\ub450 \ubb38\uc744 \uc5f4\uace0 \uc788\uc5c8\uace0 \uc99d\uad8c\uc2dc\uc7a5\ub3c4 \uc815\uc0c1\uc801\uc73c\ub85c \uac70\ub798\ub97c \ud558\uace0 \uc788\ub294 \uac70\uc57c. \uadf8\ub9ac\uace0 \uac00\uc7a5 \ub180\ub77c\uc6e0\ub358 \uac83\uc740 \uc8fc\uac00 \uc9c0\uc218\uac00 180\ub3c4 \uc120\ud68c\ud558\uc5ec \uadf8 6\uac1c\uc6d4 \ub3d9\uc548 \uc9c0\uc18d\uc801\uc73c\ub85c \uc0c1\uc2b9\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774\uc9c0. \uc774\uac83\uc774\uc57c\ub9d0\ub85c \uc644\ubcbd\ud55c \ud329\ud140 \ucf64\ud50c\ub9ac \ud604\uc0c1\uc774\ub77c\uace0 \ub9d0\ud560 \uc218 \uc788\uc9c0.\" \u2014 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\n\n---\n\n## \ud3ec\uc778\ud2b8 22\n\n\ud329\ud140 \ucf64\ud50c\ub9ac \ud604\uc0c1\uc758 \uacb0\ub860:\n\n> \"\ub2f9\uc2e0\uc758 \ub17c\ub9ac\ub294 \ub2e8\uc9c0 \ud1b5\uacc4\uc801\u00b7\uacbd\uc81c\uc801\u00b7\uc815\uce58\uc801 \uc694\uc18c\ub4e4, \uc989 \uc18c\uc704 \uae30\ubcf8\uc801\uc778 \uc694\uc18c\ub4e4\uc5d0\ub9cc \uc758\uc9c0\ud558\uace0 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774\ub7ec\ud55c \ubaa8\ub4e0 \uac83\ub4e4\uc740 \uae30\uc220\uc801 \uc694\uc778\ub4e4(\uc218\uc694\uc640 \uacf5\uae09\uc758 \ubc95\uce59, \ud070 \uc190\uacfc \uc791\uc740 \uc190\uc758 \ubc95\uce59 \ub4f1)\uc5d0 \uc758\ud574 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \ud55c\ub9c8\ub514\ub85c \ub2f9\uc2e0\uc758 \uc0dd\uac01\uc740 \ub108\ubb34\ub098\ub3c4 \uc774\ub860\uc801\uc774\ub2e4. \uadf8\ub807\uae30 \ub54c\ubb38\uc5d0 \uadf8\uac83\ub4e4\uc740 \ud604\uc2e4\uacfc\ub294 \ub9de\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4.\"\n\n**\uc99d\uad8c\uc2dc\uc7a5\uacfc \uacbd\uae30\ubcc0\ub3d9\uc758 \ucd94\uc138\ub294 \uc11c\ub85c \uc0c1\ud638\uc791\uc6a9\ud558\uace0 \uc788\uc73c\uba70 \ub3d9\uc77c\ud55c \ubc95\uce59\uc5d0 \uc758\ud574 \uc9c0\ubc30\ub418\uace0 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uacb0\ucf54 \ud3c9\ud589\uc120\uc0c1\uc5d0\uc11c \uc9c4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 23\n\n\uc2ec\ub9ac\uc640 \uae30\uc5c5\uc758 \ud380\ub354\uba58\ud138\uc774 \uc11c\ub85c \ubc18\ub300\ub418\ub294 \uc0c1\ud669, \uc989 \uc2ec\ub9ac\ub294 \uae0d\uc815\uc801\uc774\ub098 \ud380\ub354\uba58\ud138\uc740 \ubd80\uc815\uc801\uc778 \uacbd\uc6b0 \ub610\ub294 \uadf8 \ubc18\ub300\uc758 \uacbd\uc6b0, \uc8fc\uac00\ub294 \uc0c1\uc2b9\ud560 \uc218\ub3c4 \ud558\ub77d\ud560 \uc218\ub3c4 \uc788\ub2e4.\n\n**\ud558\uc9c0\ub9cc \uc6b0\ub9ac\uac00 \uc8fc\ubaa9\ud574\uc57c \ud560 \ud3ec\uc778\ud2b8\ub294 \uc2ec\ub9ac\uc640 \ud380\ub354\uba58\ud138\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc77c \ub54c\ub2e4. \uc2ec\ub9ac\uc640 \ud380\ub354\uba58\ud138 \ubaa8\ub450 \ubd80\uc815\uc801\uc774\ub77c\uba74 \uc8fc\uac00\ub294 \uae09\ub77d\ud558\uba70, \uc2ec\ub9ac\uc640 \ud380\ub354\uba58\ud138\uc774 \ubaa8\ub450 \uae0d\uc815\uc801\uc774\ub77c\uba74 \uc8fc\uac00\ub294 \uae09\ub4f1\ud55c\ub2e4.** \ub530\ub77c\uc11c \uc6b0\ub9ac\ub294 \uc2ec\ub9ac\uc640 \ud380\ub354\uba58\ud138\uc744 \ubaa8\ub450 \uc2e0\uacbd \uc4f0\uba70 \ud22c\uc790\ud574\uc57c \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 24\n\n\uc5b4\ub5a4 \uc8fc\uc2dd\uc5d0 \ub300\ud55c \ud3c9\uac00\ub294 \ud22c\uc790\uc790\ub4e4\uc5d0\uac8c \ub2ec\ub824 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ud3c9\uac00\ub294 \uc0ac\ub78c\ub9c8\ub2e4 \ub2e4\ub974\uba70, \ub3d9\uc77c\ud55c \uc0ac\ub78c\uc774\ub77c\ub3c4 \uc804\ub9dd\uacfc \ubbf8\ub798\uc5d0 \ub300\ud55c \ud3c9\uac00\ub294 \ub0a0\ub9c8\ub2e4 \ubcc0\ud55c\ub2e4. \uacb0\uad6d \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc804\uccb4 \ubd84\uc704\uae30\ub294 \uc99d\uad8c\uc2dc\uc7a5 \ucc38\uc5ec\uc790\ub4e4 \uac04\uc758 \ud0c0\ud611\uc5d0 \ub2ec\ub824 \uc788\ub2e4. **\uadf8\ub4e4\uc758 \uacfc\ubc18\uc218\uac00 \ub099\uad00\uc801\uc778\uc9c0 \ube44\uad00\uc801\uc778\uc9c0\uc5d0 \ub300\ud55c \ud0c0\ud611 \ub9d0\uc774\ub2e4.**\n\n\uc774\ub85c\ubd80\ud130 \ubc1c\uc0dd\ud558\ub294 \uc18c\uc704 \uc99d\uad8c\uc2dc\uc7a5 \ubd84\uc704\uae30\ub294 \uc2dc\uc138\uc5d0 \uacb0\uc815\uc801\uc778 \uc601\ud5a5\uc744 \ubbf8\uce5c\ub2e4. **\uc989 \uc774\ub7f0 \ubd84\uc704\uae30\ub97c \ube68\ub9ac \uc54c\uc544\ucc28\ub9b0\ub2e4\uba74, \uc9c0\uae08 \uc8fc\uc2dd\uc744 \ub9e4\uc218\ud574\uc57c \ud558\ub294\uc9c0 \ub9e4\ub3c4\ud574\uc57c \ud558\ub294\uc9c0 \uc54c \uc218 \uc788\ub294 \uac83\uc774\ub2e4.** \ubd84\uc704\uae30\uac00 \uc5b4\ub5bb\uac8c \ud615\uc131\ub418\ub294\uc9c0 \uaf2d \uc9d1\uc5b4\uc11c \ub9d0\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uadf8\ub9ac\uace0 \uc774\ub7f0 \ubd84\uc704\uae30\ub294 \uacb0\ucf54 \ub17c\ub9ac\ud559\uc744 \ub530\ub974\uc9c0 \uc54a\uc73c\uba70, \uc790\uc8fc \uc804\ubb38\uac00\ub4e4\uc744 \ub180\ub77c\uac8c \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 25\n\n\uc6b0\ub9ac\uac00 \uc0ac\ub294 \uc138\uc0c1\uc740 \ubc00\ubb3c\uacfc \uc370\ubb3c \uac19\uc740 \uc21c\ud658, \uc0ac\uacc4\uc808\uc758 \uc5f0\uc18d \ubcc0\ud654, \ub04a\uc784\uc5c6\ub294 \uc21c\ud658 \ub4f1\uc758 \uc790\uc5f0 \uc0c1\ud0dc\ub97c \ubcf4\uc5ec\uc900\ub2e4. \uc0ac\ud68c\uc801 \uc0b6 \uc18d\uc5d0\uc11c \uc6b0\ub9ac\ub294 \uacbd\uc81c\uc5d0\uc11c\uc758 \ud638\ud669\uacfc \ubd88\ud669, \uc804\uc7c1\uacfc \ud3c9\ud654, \ub099\uad00\uacfc \ube44\uad00 \ub4f1\uc758 \uc21c\ud658\uc744 \ub9cc\ub098\uac8c \ub41c\ub2e4. **\uc99d\uad8c\uc2dc\uc7a5\ub3c4 \uc774\uc640 \ub611\uac19\ub2e4. \uc774\uacf3\uc5d0\uc11c\ub3c4 \ub300\uc911 \uc2ec\ub9ac\uac00 \uacb0\uc815\uc801\uc778 \uc694\uc778\uc73c\ub85c \uc791\uc6a9\ud558\uc5ec \uc774\ub7ec\ud55c \ub04a\uc784\uc5c6\ub294 \uc6c0\uc9c1\uc784\uc744 \uac00\ub2a5\ucf00 \ud55c\ub2e4.**\n\n\ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 \uc2ed\uc218 \ub144\uac04\uc758 \uacbd\ud5d8\uacfc \uad00\ucc30\uc744 \uac70\uccd0 \uc8fc\uc2dd, \ucc44\uad8c, \uadc0\uae08\uc18d, \uc6d0\uc790\uc7ac \ud22c\uc790\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub294 \ubaa8\ub4e0 \uc2dc\uc7a5\uc5d0\uc11c\uc758 \uc21c\ud658\uc801 \uc2dc\uc138 \uc6c0\uc9c1\uc784\uc5d0 \uad00\ud55c \uc774\ub860\uc744 \uac1c\ubc1c\ud588\ub2e4. \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc21c\ud658\uc740 \ub2e4\uc74c \uc138 \uc885\ub958\uc758 \ubc1c\uc804 \ub2e8\uacc4\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\ub2e4.\n\n1. **\uccab \ubc88\uc9f8 \ub2e8\uacc4: \uc870\uc815 \uad6d\uba74** \u2014 \uc544\uc8fc \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d\ud588\ub358 \uc2dc\uc138\uac00 \uc5b4\ub290 \uc815\ub3c4 \ud604\uc2e4\uc801\uc774\uace0 \uc801\ub2f9\ud55c \uc218\uc900\uc73c\ub85c \uc870\uc815\ub41c\ub2e4.\n2. **\ub450 \ubc88\uc9f8 \ub2e8\uacc4: \uc801\uc751 \uad6d\uba74 (\ub3d9\ud589 \uad6d\uba74)** \u2014 \uc2dc\uc138\ub294 \uc9c4\ud589\ub418\ub294 \uc0ac\uac74\ub4e4\uacfc \ud3c9\ud589\uc73c\ub85c \ubc1c\uc804\ud558\uac8c \ub41c\ub2e4. \uc0ac\uac74\ub4e4\uc774 \uc545\uc7ac\ub85c \uc791\uc6a9\ud558\uba74 \uc2dc\uc138\ub294 \ub5a8\uc5b4\uc9c0\uace0, \ud638\uc7ac\ub85c \uc791\uc6a9\ud558\uba74 \uc2dc\uc138\ub294 \uc0c1\uc2b9\ud55c\ub2e4.\n3. **\uc138 \ubc88\uc9f8 \ub2e8\uacc4: \uacfc\uc7a5 \uad6d\uba74** \u2014 \uc8fc\uac00\uc758 \uc0c1\uc2b9\uacfc \ubd84\uc704\uae30\uac00 \uc0c1\ud638 \uc601\ud5a5\uc744 \uc8fc\uace0\ubc1b\uc73c\uba70 \uc8fc\uac00\ub294 \ub2e8\uacc4\uc801\uc73c\ub85c \uc0c1\uc2b9\ud55c\ub2e4. \uc0c1\uc2b9\ub41c \uc2dc\uc138\ub294 \uc7a5\ubc0b\ube5b \ubd84\uc704\uae30\ub97c \ub9cc\ub4e4\uc5b4\ub0b4\uace0 \ub099\uad00\ub860\uc790\ub4e4\uc740 \ub73b \ubaa8\ub97c \ud589\ubcf5\uac10\uc5d0 \uc816\uac8c \ub41c\ub2e4.\n\n\uc138 \ubc88\uc9f8 \ub2e8\uacc4\ub294 \uc544\uc8fc \ucc9c\ucc9c\ud788 \uc2e4\ud589\ub41c\ub2e4. \ud558\uc9c0\ub9cc \uad6d\uba74 \uc804\ud658\uc740 \uc5b4\ub290 \ub0a0 \uac11\uc790\uae30, \ub69c\ub837\ud55c \ub3d9\uae30\ub3c4 \uc5c6\uc774, \uc544\ubb34\ub7f0 \uc900\ube44\ub3c4 \ub418\uc5b4 \uc788\uc9c0 \uc54a\uc740 \ud22c\uc790\uc790\ub4e4\uacfc \ud2b9\ud788 \uc804\ubb38\uac00\ub4e4\uc5d0\uac8c \uc544\uc8fc \ucee4\ub2e4\ub780 \ub180\ub77c\uc6c0\uc744 \uc120\uc0ac\ud558\uba70 \uc2dc\uc7a5\uc758 \uc2dc\uc138\ub294 \uadf9\uc801\uc73c\ub85c \ubc18\uc804\ud55c\ub2e4.\n\n> \uc774\uac83\uc774 \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc601\uc6d0\ud55c \ud68c\uc804, \ud639\uc740 \uc724\ud68c\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 26\n\n\ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \uc21c\ud658 \uc18d \ud589\ub3d9 \uc9c0\uce68:\n\n- **\uc870\uc815 \uad6d\uba74\uc5d0\uc11c\ub294 \ub9e4\uc785\ud55c\ub2e4.** \uc8fc\uac00\uac00 \ub354 \ub5a8\uc5b4\uc9c4\ub2e4\uace0 \ud558\ub354\ub77c\ub3c4 \ub180\ub77c\uac70\ub098 \ud5c8\ub465\ub300\uba74 \uc548 \ub41c\ub2e4.\n- **\uc801\uc751 \uad6d\uba74\uc5d0\uc11c\ub294 \uadf8\ub0e5 \uc9c0\ucf1c\ubcf8\ub2e4.**\n- **\uacfc\uc7a5 \uad6d\uba74\uc73c\ub85c \ub118\uc5b4\uac00\uba74 \uc2dc\uc7a5\uc744 \uc9c0\ubc30\ud558\uace0 \uc788\ub294 \ud589\ubcf5\uac10\uacfc \ud568\uaed8 \ucde8\ud558\uba70 \uc990\uae34\ub2e4.** \uadf8 \uc640\uc911\uc5d0 \uc870\uc6a9\ud788 \ub9e4\ub3c4\ub97c \uc900\ube44\ud558\uba74 \ub41c\ub2e4.\n\n**\uc6b0\ub9ac\uac00 \uc774 \uc21c\ud658\uc801 \uc6c0\uc9c1\uc784 \uc18d\uc5d0\uc11c 3\ubd84\uc758 2\uc758 \uae30\uac04 \ub3d9\uc548\uc740 \ucd94\uc138\uc640 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc5ec\uc57c \ud558\uba70, 3\ubd84\uc758 1\uc758 \uae30\uac04 \ub3d9\uc548\uc5d0\ub294 \ucd94\uc138\uc640 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\uba74 \ub41c\ub2e4.** \ubb3c\ub860 \uc774\uac83\uc740 \ub9e4\uc6b0 \uc5b4\ub824\uc6b4 \uc77c\uc774\ub2e4. \uc65c\ub0d0\ud558\uba74 \uad70\uc911 \uc2ec\ub9ac\uc758 \uc555\ub825\uc5d0 \ub300\ubd80\ubd84 \uc27d\uac8c \uad74\ubcf5\ud558\uace0 \ub9d0\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n\ub530\ub77c\uc11c \ud22c\uc790\uc790\ub294 \uad70\uc911\uc758 \ud788\uc2a4\ud14c\ub9ac\ub97c \ub5a8\uccd0 \ubc84\ub9ac\uae30 \uc704\ud574\uc11c \ub9ce\uc740 \ud6c8\ub828\uc744 \ud574\uc57c \ud55c\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc744 \ubbff\uc9c0 \ub9d0\uc544\uc57c \ud558\uba70, \uc870\uae08\uc740 \uac74\ubc29\uc9c4 \uba74\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4.\n\n> \"\ub108\ud76c\ub4e4\uc740 \ubaa8\ub450 \ubc14\ubcf4\uc57c. \ub098 \ud63c\uc790\ub9cc \ubb54\uac00\ub97c \uc54c\uace0 \uc788\uc9c0.\"\n\n\uc774\uac83\uc744 \ud6cc\ub96d\ud55c \ud2b9\uc131\uc774\ub77c\uace0 \ub9d0\ud560 \uc21c \uc5c6\uc9c0\ub9cc, \uc2a4\uc2a4\ub85c \uc0dd\uac01\ud558\uae30 \uc704\ud574 \uadf8\ub9ac\uace0 \uc131\uacf5\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc544\uc8fc \uc720\uc775\ud55c \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 27\n\n**\ud22c\uc790\uc5d0\uc11c \ud655\uc2e4\ud788 \uc131\uacf5\ud558\ub824\uba74 \uc0c1\ud669\uc744 \uc815\ud655\ud788 \ud310\ub2e8\ud574\uc57c \ud560 \ubfd0\ub9cc \uc544\ub2c8\ub77c, \ub2e4\ub978 \ubaa8\ub4e0 \uc0ac\ub78c\ub4e4\uc774 \uc798\ubabb\ub418\uc5b4 \uc788\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc804\uc81c\uac00 \ud544\uc694\ud558\ub2e4.** \ub9cc\uc57d \uae08\uc735\uacc4\uc5d0\uc11c \uc5b4\ub5a4 \uc77c\uce58\ub41c \ud569\uc758\uac00 \uc774\ub8e8\uc5b4\uc9c4\ub2e4\uba74, \uc131\uacf5\uc801\uc778 \ud22c\uc790\uc790\ub4e4\uc740 \uc989\uc2dc \uadf8 \uc18c\uc2dd\uc744 \uae30\uc05c \ub9c8\uc74c\uc73c\ub85c \ubc1b\uc544\ub4e4\uc778\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc758\uacac\uc740 \uc798\ubabb\ub418\uac8c \ub9c8\ub828\uc774\ubbc0\ub85c, \uc774\uc81c \uadf8 \uc131\uacf5\uc801\uc778 \ud22c\uc790\uc790\uc5d0\uac8c\ub294 \uc0ac\ub0e5\uac10\uc774 \ud48d\ubd80\ud55c \uc0ac\ub0e5\ud130\uac00 \uc5f4\ub9b4 \uac83\uc774\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 28\n\n\ub2e8\uacc4\uc5d0\uc11c \ub2e8\uacc4\ub85c \uc5b8\uc81c \ub118\uc5b4\uac08 \uac83\uc778\uac00\ub97c \uc815\ud655\ud788 \uacc4\uc0b0\ud560 \uc218 \uc788\ub294 \uacfc\ud559\uc801 \ubc29\ubc95\uc740 \uc5c6\ub2e4. \ud558\ub098\uc758 \uc0c1\uc2b9 \uc6b4\ub3d9\uc740 1\ub144\uc774 \uac78\ub9b4 \uc218\ub3c4 \uc788\uace0 \ub2e8\uc9c0 \uba87 \ub2ec\uc774 \uac78\ub9b4 \uc218\ub3c4 \uc788\ub2e4. **\uc0ac\ub78c\ub4e4\uc740 \uc790\uc2e0\ub4e4\uc758 \uacbd\ud5d8\uc744 \ubc14\ud0d5\uc73c\ub85c \uc774\ub7ec\ud55c \uc9c0\ud45c\ub97c \uc2a4\uc2a4\ub85c \ucc3e\uc544\ub0b4\uc57c \ud55c\ub2e4.**\n\n> \"\ub9cc\uc57d \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc2dc\uc138 \ub610\ub294 \ucd94\uc138\ub97c \ud559\ubb38\uc801 \ubc29\ubc95\uc744 \uac00\uc9c0\uace0 \uc608\uce21\ud558\uace0\uc790 \ud558\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4\uba74, \uadf8\ub294 \uc0ac\uae30\uafbc\uc774\uac70\ub098 \ubc14\ubcf4\uc774\ub2e4.\"\n\n\ub9e4\uc6b0 \uc624\ub79c \uacbd\ud5d8\uc744 \ud1b5\ud574\uc11c\ub9cc \ud754\ud788\ub4e4 '\uc190\uac00\ub77d \ub05d \uac10\uac01'\uc774\ub77c\uace0 \ubd80\ub974\ub294 \uac83\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \uadf8\ub9ac\uace0 \uadf8 \uac10\uac01\uc744 \uc5bb\uae30 \uc704\ud574\uc11c\ub294 \uc790\uc8fc \ud5e4\ub9e4\uc57c \ud55c\ub2e4. \uc989 \uc2e4\uc218\ub97c \ub9ce\uc774 \ud574\ubd10\uc57c \ud55c\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uc77c\uacfc \ub300\uc911\uc758 \ubc18\uc751\uc744 \uc808\ub300\ub85c \uc608\uc5b8\ud560 \uc218 \uc5c6\ub2e4. **\ub2e8\uc9c0 \ucd94\uce21\ud560 \ubfd0\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 29\n\n\uc8fc\uac00 \ud3ed\ub77d\uc740 \uac11\uc791\uc2a4\ub7fd\uac8c \uadf8\ub9ac\uace0 \uc2e0\ub4e4\uc758 \ubcf5\uc218\uc640\ub3c4 \uac19\uc774 \uaca9\ub82c\ud558\uac8c \uc624\ub294 \ubc18\uba74\uc5d0, \uc2dc\uc138\uac00 \uc0c1\uc2b9\ud560 \ub54c\ub294 \ubd80\ub4dc\ub7fd\uae30 \uadf8\uc9c0\uc5c6\ub2e4. \uc99d\uad8c\uc2dc\uc7a5\uc774 \uc798 \ub3cc\uc544\uac00\uba74 \ud22c\uc790\uc790\uc5d0\uac8c \uc9c0\uadf9\ud788 \uc815\uc0c1\uc801\uc778 \uac83\uc73c\ub85c \ubcf4\uc774\uace0 \uc9c8\uc11c\uac00 \uc7a1\ud78c \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub294 \uc0c1\ud669\uc774 \uc798\ubabb \ub3cc\uc544\uac08 \uc218 \uc788\ub2e4\ub294 \uac83\uc744, \ub354\uc6b1\uc774 \ud3ed\ub825\uc801\uc73c\ub85c \ub3cc\ubcc0\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \uc0c1\uc0c1\uc870\ucc28 \ud558\uc9c0 \ubabb\ud55c\ub2e4.\n\n1987\ub144 \uc5ec\ub984, \uc544\ubb34\ub7f0 \uae4c\ub2ed\ub3c4 \uc5c6\uc774 \uae08\ub9ac\uac00 \ucc9c\ucc9c\ud788 \uc624\ub974\uae30 \uc2dc\uc791\ud588\ub2e4. \uadf8\ub7ec\ub098 \uae08\ub9ac\uac00 \uc624\ub974\ub294 \uac83\ubcf4\ub2e4 \ub099\uad00\ub860\uc790\ub4e4\uc758 \uc804\ub9dd\uc774 \ub354 \uc6b0\uc138\ud588\uace0, \uc8fc\uc2dd \uc2dc\uc138\ub294 \uacc4\uc18d\ud574\uc11c \ub192\uc774 \uce58\uc19f\uc558\ub2e4. \uadf8\ub7ec\uc790 \ub3c5\uc77c \uc5f0\ubc29\uc740 \uc778\ud50c\ub808\uc774\uc158\uc744 \uc5b5\uc81c\ud558\uae30 \uc704\ud574 \uc774\uc790\uc728\uc744 \ub192\uc600\ub2e4. \uadf8 \ub4a4\ub97c \ub530\ub77c \ubbf8\uad6d \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4 \uc774\uc0ac\ud68c\uac00 \uae08\ub9ac\ub97c \uc62c\ub838\ub2e4. \uadf8\uac83\uc774 \ubc14\ub85c \ubd80\ud480\ub300\ub85c \ubd80\ud47c \ud48d\uc120\uc744 \ud130\ub728\ub9b0 \ubc14\ub298\uc758 \ub05d\uc774\uc5c8\ub2e4.\n\n> **\ud638\ud669\uc740 \ubcc0\ud615\uc758 \ub9ac\ub4ec \uc18d\uc5d0\uc11c \ub3fc\uc9c0 \uad00\uad11\ucc98\ub7fc \uc11c\uc11c\ud788 \ud33d\ucc3d\ud55c\ub2e4. \uadf8\ub7ec\ub2e4\uac00 \uc5b4\ub290 \ub0a0 \uac11\uc790\uae30 \ub3cc\uc544\ubcf4\uba74 \ubc14\ub298 \ub05d \ud558\ub098\uc5d0 \uc758\ud574 \ud130\uc838 \ubc84\ub9b4 \ub9cc\ud07c\uc758 \ud48d\uc120\uc774 \ub418\uc5b4 \uc788\ub2e4. \uadf8\ub9ac\uace0 \uadf8 \ud48d\uc120\uc740 \uc544\uc8fc \ubbf8\uc138\ud55c \uc6c0\uc9c1\uc784\uc5d0 \ud130\uc838 \ubc84\ub9b0\ub2e4.**\n\n\ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 \uc8fc\uc2dd \uc2dc\uc138\ub97c \uae09\ubcc0\uc2dc\ud0a4\ub294 \uc694\uc778\uc744 \ubcc0\ub355\uc2a4\ub7ec\uc6b4 \uae30\uad00\ud22c\uc790\uc790\ub4e4\uc774\ub77c\uace0 \ub9d0\ud558\uace0 \uc788\ub2e4. \uadf8\ub4e4\uc758 '\ubaa8\ub450 \ud314\uc544\ubc84\ub824\uc57c \ud55c\ub2e4'\ub294 \uc9d1\ub2e8 \uc2ec\ub9ac\uac00 \uc8fc\uac00\ub97c \uae09\uaca9\ud788 \ub04c\uc5b4\ub0b4\ub9b0\ub2e4\uace0 \ub9d0\ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 30\n\n\ub098\ub3c4 \ud55c\ub54c\ub294 \uc774\uc775\uc740 \uacc4\uc18d \ub098\ub3c4\ub85d \ud558\uace0 \uc190\uc2e4\uc740 \uc81c\ud55c\ud558\ub77c\ub294 \uba85\ub839\ud654\uac00 \uac00\ub2a5\ud560 \uac83\uc774\ub77c\uace0 \ubbff\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub54c\ub294 \ub0b4\uac00 \uc544\uc9c1 \uac8c\uc784\uafbc\uc774\uc5c8\uc744 \ub54c\uc600\ub2e4. **\uadf8 \ub4a4\ub85c \ub098\ub294 \ub9ce\uc740 \uac83\ub4e4\uc744 \ubc30\uc6e0\uc73c\uba70, \ud22c\uc790\uc790\ub85c 70\ub144\uc744 \ubcf4\ub0c8\ub2e4. \uadf8\ub9ac\uace0 \uc9c0\uae08\uc758 \ub098\ub294 \uc7a5\uae30\ud22c\uc790\uc790\uc774\uba70, \uadf8\uac04\uc758 \uacbd\ud5d8\uc744 \ubc14\ud0d5\uc73c\ub85c \ub300\uc911\uc801 \uc21c\ud658\uacfc \ubc18\ub300\ub85c \ud589\ub3d9\ud558\uace0 \uc7a5\uae30\uc801 \uad00\uc810\ud558\uc5d0\uc11c\ub9cc \ud070\ub3c8\uc744 \ubc8c \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc73c\ub85c \uae30\uc6b8\uac8c \ub418\uc5c8\ub2e4.**\n\n\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc790\ub294 \uc774\uc724\uc744 \ub0bc \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub294 \uacb0\uad6d\uc5d0 \uac00\uc11c\ub294 \ud30c\uc0b0\ud558\uac8c \ub41c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 31\n\n**\uc77c\ubc29\uc801\uc774\uace0 \uadfc\uc2dc\uc548\uc801\uc73c\ub85c \ub274\uc2a4\ub97c \ub530\ub77c\uac00\ub294 \uac83\uc740 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc644\uc804\ud788 \ubbf8\uce5c \uc9d3\uc774\ub2e4. \ud22c\uc790\ub294 \ud3ed\ub113\uac8c \uc0dd\uac01\ud558\uace0 \uba40\ub9ac \ubcf4\uc544\uc57c \ud55c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 32\n\n\uad6d\ub0b4 \uc815\uce58 \uc0c1\ud669, \uad6d\uc81c\uc801 \uc0c1\ud669 \ub4f1\uc774 \uc99d\uad8c\uc2dc\uc7a5\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc740 \ud06c\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ubaa8\ub4e0 \uc0c1\ud669\uc740 \uc99d\uad8c\uc2dc\uc7a5 \ucc38\uc5ec\uc790\ub4e4\uc758 \uc2ec\ub9ac\uc801 \uae30\ubcf8 \uad00\uc810\uc5d0 \ub530\ub77c \ub2e4\ub974\uac8c \ud574\uc11d\ub41c\ub2e4. **\uc8fc\uc2dd\uc2dc\uc7a5\uc758 \ubd84\uc704\uae30\uac00 \ub099\uad00\uc801\uc774\ub0d0 \ube44\uad00\uc801\uc774\ub0d0\uc5d0 \ub530\ub77c \uc815\uce58\uc640 \uacbd\uc81c\ub294 \uc804\ud600 \ub2e4\ub974\uac8c \ud574\uc11d\ub41c\ub2e4.**\n\n\ud55c \ub299\uc740 \uc99d\uad8c\uc2dc\uc7a5 \uc5ec\uc6b0\uac00 \ucd5c\uace0 \uace0\uac1d \uba87 \uba85\uacfc \ud3b8\uc548\ud558\uac8c \uc549\uc544 \uc774\uc57c\uae30\ub97c \ub098\ub204\uc5c8\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ubb3c\uc5c8\ub2e4.\n\n> \"\uc2dc\uc138 \uc0c1\uc2b9 \ud22c\uc790\uc640 \uc2dc\uc138 \ud558\ub77d \ud22c\uc790\uac00 \ub3c4\ub300\uccb4 \uc5b4\ub5bb\uac8c \uc2dc\uc791\ub418\ub290\ub0d0\ub294 \uac81\ub2c8\ub2e4?\"\n\n\ub299\uc740 \uc5ec\uc6b0\uac00 \uc124\uba85\ud588\ub2e4. \uba87 \ub144 \uc804, \uc5b4\ub290 \ub0a0 \uc624\ub798\ub41c \uc2a4\ucf54\ud2c0\ub79c\ub4dc \ud608\ud1b5\uc758 \uc80a\uace0 \uc798\uc0dd\uae34 \uc655\uc790\uac00 \ub9e4\ub825\uc801\uc778 \uc2a4\ud398\uc778 \uacf5\uc8fc\uc640 \uc57d\ud63c\uc744 \ud588\ub2e4\uace0 \uc2e0\ubb38\uc5d0 \ubcf4\ub3c4\ub41c \uc801\uc774 \uc788\uc5c8\ub2e4. \uc628 \uc138\uacc4\uac00 \uc774 \uc544\ub984\ub2e4\uc6b4 \ud55c \uc30d\uc5d0 \ub9e4\ud639\ub418\uc5c8\ub2e4. \uc774 \uc0ac\uac74\uc740 \ub300\uc911\ub4e4\uc5d0\uac8c \uae0d\uc815\uc801\uc778 \ubd84\uc704\uae30\ub97c \uc81c\uacf5\ud588\uace0 \uc77c\ubc18\uc801\uc778 \ub099\uad00\ub860\uc774 \uc720\ub7fd \uc99d\uad8c\uc2dc\uc7a5\uc5d0\ub3c4 \uc804\uc5fc\ub418\uc5c8\ub2e4. \uadf8\ub7f4\ub4ef\ud55c \uc774\uc720\ub3c4 \uc5c6\uc774 \uc2dc\uc138\ub294 \uc624\ub974\uace0 \ub610 \uc62c\ub790\ub2e4. \ub9ce\uc740 \ud22c\uc790\uc790\ub4e4\uc740 \ubd80\uc790\uac00 \ub418\uc5c8\uace0 \uacbd\uc81c\ub294 \ubc88\ucc3d\ud588\ub2e4.\n\n\uadf8\ub7ec\ub358 \uc5b4\ub290 \ub0a0 \uc804\ud600 \uae30\ub300\ud558\uc9c0 \uc54a\uc558\ub358 \ub098\uc05c \uc18c\uc2dd\uc774 \ub0a0\uc544\ub4e4\uc5c8\ub2e4. \ud63c\uc778\uc740 \uae68\uc5b4\uc9c0\uace0 \uc655\uc790\uc640 \uacf5\uc8fc\ub294 \ud5e4\uc5b4\uc84c\ub2e4. \uc774 \ub274\uc2a4\ub294 \ud558\ub098\uc758 \ucda9\uaca9\uc73c\ub85c \uc791\uc6a9\ud558\uba70 \uc99d\uad8c\uc2dc\uc7a5\uc758 \ud070 \ud3ed\ub77d\uc744 \ubd88\ub7ec\uc77c\uc73c\ucf30\ub2e4.\n\n\ucc98\uc74c\uc5d0 \uc9c8\ubb38\ud588\ub358 \uc0ac\ub78c\uc774 \ud654\uac00 \ub09c \ubaa9\uc18c\ub9ac\ub85c \ub2e4\uc2dc \ubb3c\uc5c8\ub2e4.\n\n> \"\ub3c4\ub300\uccb4 \uadc0\uc871\ub4e4\uc758 \uacb0\ud63c\uc774 \uc99d\uad8c\uc2dc\uc7a5\uacfc \ubb34\uc2a8 \uc0c1\uad00\uc774 \uc788\ub2e8 \ub9d0\uc785\ub2c8\uae4c?\"\n\n\uadf8\ub7ec\uc790 \ub299\uc740 \uc5ec\uc6b0\uac00 \ub418\ubb3c\uc5c8\ub2e4.\n\n> \"\uc774\uc0c1\ud558\uad70\uc694. \ub0b4\uac00 \ucc98\uc74c\uc5d0 \uc2dc\uc138 \uc0c1\uc2b9 \ud22c\uc790\ub97c \uc124\uba85\ud588\uc744 \ub54c\ub294 \uc65c \uadf8\ub7f0 \uc9c8\ubb38\uc744 \ud558\uc9c0 \uc54a\uc558\ub098\uc694?\"\n\n---\n\n## \ud3ec\uc778\ud2b8 33\n\n\ucc45\uc784 \uc788\ub294 \uc790\ub9ac\uc5d0 \uc788\ub294 \uc0ac\ub78c\uc758 \ud3c9\uc18c \ubc1c\uc5b8 \ud55c\ub9c8\ub514\uc5d0 \uadf8 \uc0ac\ub78c\uc744 \ubbff\ub294 \uc218\ucc9c \uba85\uc758 \ud22c\uc790\uc790\ub4e4\uc774 \uc0ac\uae30 \uc704\ud574\uc11c \ub610\ub294 \ud314\uae30 \uc704\ud574\uc11c \ub2ec\ub824 \ub098\uac04\ub2e4. \uc2ec\uc0ac\uc219\uace0\ub3c4 \ud558\uc9c0 \uc54a\uc740 \ucc44 \ub9d0\uc774\ub2e4.\n\n**\uc774\ub7f0 \ud22c\uae30\uc801 \uac70\ub798 \ud589\uc704\ub294 \uc9c0\ub09c \uc218\ub144 \ub3d9\uc548 \ub354\uc6b1 \ub2e4\uc591\ud574\uc9c4 \ubcf5\uc7a1\uc131\uacfc \ub354 \uacf5\uc138\uc801\uc778 \ud615\ud0dc\ub85c \ubc1c\uc804\ud558\uc5ec \uacbd\uc81c\uc5d0 \ub9e4\uc6b0 \ub9ce\uc740 \ud53c\ud574\ub97c \uc57c\uae30\uc2dc\ucf30\ub2e4.** \ub300\uc911 \ub9e4\uccb4\ub294 \uac00\uaca9\uc758 \ubcc0\ud654\uc640 \ubb34\uc5ed \uc2dc\uc7a5\uc5d0 \uac70\uc758 \uc5b8\uc81c\ub098 \ubd80\uc815\uc801\uc778 \uc601\ud5a5\uc744 \uc900\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 34\n\n\ud070 \uc131\uacf5\uc744 \uac70\ub454 \ud22c\uc790\uc790\ub294 \ub300\ubd80\ubd84 \ub6f0\uc5b4\ub09c \uc815\uce58\uc801 \ubd84\uc11d\uac00\uc774\uba70 \uad70\uc911 \uc2ec\ub9ac\ud559\uc790\uc774\uae30\ub3c4 \ud558\ub2e4. \uc65c\ub0d0\ud558\uba74 \uadf8\ub294 \uc815\uce58\uc801 \uc0ac\uac74\ub4e4\uacfc \uadf8\uc5d0 \ub300\ud55c \ud22c\uc790\uc790\ub4e4\uc758 \ubc18\uc751\uc774\ub77c\ub294 \ub450 \uac1c\uc758 \ud37c\uc990\uc744 \ub3d9\uc2dc\uc5d0 \ub9de\ucd94\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. **\ud558\uc9c0\ub9cc \uc77c\ubc18 \ub300\uc911\ub4e4\uc740 \ubaa8\ub4e0 \uc0ac\ub78c\ub4e4\uc774 \uc774\ubbf8 \uc54c\uace0 \uc788\ub294 \ub274\uc2a4\ub97c \ub17c\ub9ac\uc801\uc73c\ub85c\ub9cc \ud574\uc11d\ud558\ub294 \uc6b0\ub97c \ubc94\ud55c\ub2e4.**\n\n**\ube68\uac04 \uc790\uc804\uac70 \u2014 \uc544\uc8fc \uc624\ub798\uc804\uc5d0 \ub098\ub294 \uacbd\ud5d8\uc744 \ud1b5\ud574 \ubc30\uc6e0\ub2e4. \ud22c\uc790\ub97c \ud558\ub294 \uc0ac\ub78c\ub4e4\uc740 \uacb0\ucf54 \ub274\uc2a4\ub97c \ub530\ub77c\uac00\uc9c0 \ub9d0\uc544\uc57c \ud55c\ub2e4\ub294 \uac83\uc744.**\n\n1914\ub144 \ucd08\uc5ec\ub984, \uc804\uc6b4\uc774 \uac10\ub3cc\uae30 \uc2dc\uc791\ud558\uba74\uc11c \ud22c\uae30 \uc5f4\uc774 \ub098\ud0c0\ub0ac\ub2e4. \ub098\uc758 \ud615\uc740 \uc218\uc785\ud488\ubaa9 \uc911 \ud3ec\ub3c4\uc8fc \uc0dd\uc0b0\uc5d0 \uc5c6\uc5b4\uc11c\ub294 \uc548 \ub420 \ub77c\ud53c\uc544\uc5d0 \ub300\ud55c \uc815\ubcf4\ub97c \uc785\uc218\ud588\ub2e4. \uadf8\ub798\uc11c \uadf8\ub294 \uce5c\uad6c \uba87 \uba85\uacfc \ud568\uaed8 \uc678\uc0c1\uc73c\ub85c \ub77c\ud53c\uc544 \uc78e \uacc4\uc57d\uc744 \uba87 \uac74 \ud588\ub2e4. \uac00\uaca9\uc740 \ud22c\uae30\uafbc\ub4e4\uc5d0 \uc758\ud574 \uc774\ubbf8 \ud06c\uac8c \uc624\ub978 \uc0c1\ud0dc\uc600\ub2e4.\n\n\ub4dc\ub514\uc5b4 \uc804\uc7c1\uc774 \ud130\uc84c\ub2e4. \uadf8\ub7ec\uc790 \ub77c\ud53c\uc544 \uac00\uaca9\uc740 \uc3dc\uc0b4\uac19\uc774 \uce58\uc19f\uc558\ub2e4. \uadf8\ub7ec\ub098 \uc624\uc2a4\ud2b8\ub9ac\uc544\uc640 \ud5dd\uac00\ub9ac \uad70\uc778\ub4e4\uc774 \uc544\uc8fc \ube60\ub974\uac8c \uc138\ub974\ube44\uc544 \uae4a\uc219\uc774 \ub3cc\uaca9\ud588\ub2e4. \uc678\uad00\uc0c1\uc758 \uc2b9\ub9ac\ub294 \uba38\uc9c0\uc54a\uc544 \ud3c9\ud654\ub97c \uae30\ub300\ud558\uac8c \ud588\ub2e4. \ub530\ub77c\uc11c \ubaa8\ub4e0 \uac83\uc774 \uace7\ubc14\ub85c \ub2e4\uc2dc \uc815\uc0c1\ud654\ub418\uc5b4 \uac14\ub2e4. \ub77c\ud53c\uc544\uc758 \uc2dc\uc138\ub294 \uae09\uc18d\ub3c4\ub85c \ubbf8\ub044\ub7ec\uc9c0\uae30 \uc2dc\uc791\ud588\ub2e4.\n\n\ud615\uc758 \uc5bc\uad74\uc740 \uc544\uce68\uc2dd\uc0ac \ub54c \ub2e4\ub974\uace0 \uc800\ub141 \uc2dd\uc0ac \ub54c \ub2e4\ub974\uac8c \uc810\uc810 \uc6b0\uc6b8\ud574\uc838 \uac14\ub2e4. \ub04a\uc784\uc5c6\ub294 \uc0c1\uc2b9\uacfc \ud558\ub77d\uc5d0 \ub530\ub978 \uac10\uc815\uc758 \ub864\ub7ec\ucf54\uc2a4\ud130\ub97c \uc6b0\ub9ac\uc758 \uac00\uc871\ub4e4\uc774 \ubaa8\ub450 \uacbd\ud5d8\ud574\uc57c \ud588\ub2e4. \uc740\ud589\uc758 \ub3c5\ucd09\uc744 \ubc1b\uc544 \uacf5\ud3ec\uc5d0 \ub5a8\ub358 \ud615\uc774 \uc790\uc0b4\uc744 \uc5b8\uae09\ud558\uc790 \uc6b0\ub9ac\ub4e4\uc740 \ubaa8\ub450 \ub5a8\uc5c8\ub2e4. \uacb0\uad6d \uc544\ubc84\uc9c0\ub294 \ud615\uc744 \ub3c4\uc640\uc8fc\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \ud615\uc774 \ub098\uc5d0\uac8c \uc0ac\uc8fc\uae30\ub85c \ud55c \ube68\uac04 \uc790\uc804\uac70\ub97c \ub098\ub294 \uac00\uc9c8 \uc218 \uc5c6\uc5c8\ub2e4.\n\n\ub098\uc758 \ubd80\ubaa8\ub2d8, \ud615, \uadf8\ub9ac\uace0 \uc774 \uc774\uc57c\uae30\uc5d0 \uc5b8\uae09\ub41c \uc778\ubb3c\ub4e4\uc740 \uc774\ubbf8 \uc624\ub798\uc804\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \ub77c\ud53c\uc544 \ud22c\uae30\ub294 \uac70\ub300\ud55c \ud22c\uae30\ub4e4\uacfc \ube44\uad50\ud558\uba74 \ud558\ucc2e\uace0 \ub2e8\uc21c\ud55c \uac83\uc774\uc9c0\ub9cc, \ub098\ub294 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \uc5ec\uc804\ud788 \ub2f9\uc2dc\uc758 \ub180\ub77c\uc6c0\uc744 \ubf08 \uc18d\uae4c\uc9c0 \ub290\ub07c\uace0 \uc788\ub2e4. **\uadf8 \ub180\ub77c\uc6c0\uc740 \ub098\uc5d0\uac8c \uc778\uc0dd\uc5d0 \ub300\ud55c \uacbd\uace0\uc640 \ub354\ubd88\uc5b4 \ub0b4\uac00 \ud558\ub294 \ud22c\uc790\uc5d0 \ub300\ud55c \uacbd\uace0\ub85c \ub0a8\uc544\uc788\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 35\n\n\ud2b9\ud788 \uc99d\uad8c\uc2dc\uc7a5\uc758 \ud589\ubcf5\uac10\uc774 \ub118\uccd0\ub098\ub294 \uc2dc\uae30\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubcc4\uc7a5\uc5d0\uc11c\uc758 \uc800\ub141 \uc2dd\uc0ac \uc911, \uce75\ud14c\uc77c \ud30c\ud2f0 \uc911, \ub610\ub294 \uc758\ud68c \ub300\uae30\uc2e4 \ub4f1 \ubaa8\ub4e0 \uacf3\uc5d0\uc11c \uc624\ub85c\uc9c0 \ud22c\uc790\uc5d0 \ub300\ud574\uc11c\ub9cc \uc774\uc57c\uae30\ub97c \ud55c\ub2e4. \uc815\ubcf4\ub97c \uad50\ud658\ud558\uace0 \ud2b9\uc815 \uc8fc\uc2dd\uc5d0 \ub300\ud55c \ubd84\uc11d\uc744 \ud55c\ub2e4. \uc774\ub54c \uc99d\uad8c \uad00\ub828 \uc9c1\uc5c5\uc740 \uc874\uacbd\uc758 \ub300\uc0c1\uc774 \ub41c\ub2e4.\n\n**\uadf8\ub7ec\ub098 \uc8fc\uc2dd\ud22c\uc790\uac00 \uc7a5\uc548\uc758 \ud654\uc82f\uac70\ub9ac\uac00 \ub418\ub294 \ubc14\ub85c \uadf8 \uc2dc\uc810\uc5d0\uc11c \ud22c\uc790\uc790\ub4e4\uc740 \ubb34\uc870\uac74 \ud558\ucc28\ud574\uc57c \ud55c\ub2e4.**\n\n\uadf8 \uc88b\uc740 \uc608\uac00 1961\ub144 \uc988\uc74c\uc774\ub2e4. \uc6d4\uc2a4\ud2b8\ub9ac\ud2b8\ub294 \ub0a0\ub9c8\ub2e4 \ucd95\uc81c\uac00 \uc5f4\ub838\uace0 \ud22c\uc790\uc790\ub4e4\uc740 \uc544\ub984\ub2e4\uc6b4 \uc0b6\uc744 \uad6c\uac00\ud588\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc8fc\uba38\ub2c8\ub97c \ucc44\uc6b0\uae30 \uc704\ud574\uc11c \ub9ce\uc740 \uac83\uc744 \uacf5\ubd80\ud560 \ud544\uc694\uac00 \uc5c6\uc5c8\uc73c\uba70, \ub2e8\uc9c0 \uc624\ub298 \uc0ac\uc11c \ub0b4\uc77c \ud314\uac70\ub098 \ub0b4\uc77c \uc0ac\uc11c \ubaa8\ub808 \ud314\uae30\ub9cc \ud558\uba74 \ub418\uc5c8\ub2e4. \uc774\uc640 \ub611\uac19\uc740 \uc0c1\ud669\uc740 1980\ub144\ub300 \ud6c4\ubc18 \ub3c5\uc77c\uc5d0\uc11c\ub3c4 \uc788\uc5c8\ub2e4. \uc624\uc804\uc5d0 \uc0c8\ub85c \ubc1c\ud589\ub41c \uc8fc\uc2dd\ub4e4\uc774 10\ub2ec\ub7ec\uc5d0 \ub098\uc624\uba74, \uc624\ud6c4\uc5d0\ub294 \uc774\ubbf8 20\ub2ec\ub7ec \ub610\ub294 30\ub2ec\ub7ec\uac00 \ub418\uc5c8\ub2e4. \uc774\uac83\uc774 \uacb0\uad6d 1962\ub144 \ud3ed\ub77d\uc73c\ub85c \ub05d\uc774 \ub09c \uadf8 \uc720\uba85\ud55c \uac70\ud488\uc774\uc5c8\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 36\n\n\uc5b4\ub290 \ub808\uc800\uc0b0\uc5c5 \ud68c\uc0ac\uac00 \ucc98\uc74c\uc73c\ub85c \uc8fc\uc2dd \uc2dc\uc7a5\uc5d0 \uc0c1\uc7a5\ud588\ub2e4. \uc18c\uc561 \ud22c\uc790\uc790\ub4e4\uc740 \uc18c\ub7c9\uc758 \uc8fc\uc2dd\uc774\ub77c\ub3c4 \ud560\ub2f9\ubc1b\uae30 \uc704\ud574 \ub108\ub3c4\ub098\ub3c4 \uc2e0\uccad\uc744 \ud588\ub2e4. \uacf5\ubaa8\uac00\ub294 370\ub9c8\ub974\ud06c\ub85c \ucc45\uc815\ub418\uc5c8\uc9c0\ub9cc, \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc774\ubbf8 500\ub9c8\ub974\ud06c\ub85c \uac70\ub798\uac00 \uc2dc\uc791\ub418\uc5c8\ub2e4.\n\n\uadf8\ub7f0\ub370 \uc8fc\uac00\uac00 1,000\ub9c8\ub974\ud06c\ub97c \ub118\uc790 \uc601\uad6d\uc5d0\uc11c \ub9ce\uc740 \ub9e4\ub3c4 \ubb3c\ub7c9\uc774 \uc3df\uc544\uc838 \ub098\uc654\ub2e4. \uadf8\uc804\uc5d0\ub294 \uc0ac\uace0 \uc2f6\uc5b4\ub3c4 \uc5c6\uc5b4\uc11c \ubabb \uc0c0\ub358 \uc0ac\ub78c\ub4e4\uc740 \uc774\uc81c \ucda9\ubd84\ud788 \ubcf4\uc720\ud558\uace0\uc790 \ud588\ub2e4. \ubbf8\uad6d \uc99d\uc2dc\uc5d0\uc11c \uc790\ubcf8\uae08\uc744 \ub0a0\ub838\ub358 \uc740\ud589\ub4e4\uc740 \uc774 \ubaa8\ub4e0 \uac83\uc774 \uc21c\uc804\ud788 \uc2ec\ub9ac\ud559 \uc694\uc778\uc5d0 \uc758\ud55c \ud604\uc0c1\uc774\ub77c\ub294 \uac83\uc744 \uc54c\uc558\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \uc740\ud589\ub4e4\uc740 \uacc4\uc18d\ud574\uc11c \ub300\uc911\ub4e4\uc5d0\uac8c \ub9e4\uc218\ud560 \uac83\uc744 \uad8c\ud588\ub2e4. \ubb3c\ub860 \uadf8\ub4e4\uc758 \uc758\ub3c4\ub294 \uc790\uc2e0\ub4e4\uc758 \uc7ac\uace0\ub97c \uc815\ub9ac\ud558\ub824\ub294 \uac83\uc774\uc5c8\ub2e4.\n\n> **\"\ubb34\uc2a8 \uc77c\uc774 \uc788\uc5b4\ub3c4 \uc740\ud589\uc758 \ucda9\uace0\ub97c \ub530\ub974\uc9c0 \ub9c8\uc2dc\uc624.\"** \u2014 \ucf54\uc2a4\ud1a8\ub77c\ub2c8, \uc138\ubbf8\ub098\uc5d0\uc11c \ubc18\ubcf5\ud558\ub294 \ub9d0\n\n\ub9c8\uce68\ub0b4 \ud48d\uc120\uc774 \ud130\uc9c0\uace0 \ub9d0\uc558\ub2e4. \ud6d7\ub0a0 \uadf8 \uc8fc\uc2dd\uc744 \ubc1c\ud589\ud588\ub358 \uc740\ud589\uc5d0\uc11c \uac15\uc5f0\ud560 \uae30\ud68c\uac00 \uc788\uc5c8\ub294\ub370 \uc624\ud398\ub77c\uc758 \ud55c \uad6c\uc808\uc744 \uc778\uc6a9\ud558\uc5ec \uc740\ud589\uc7a5\ub4e4\uc758 \ucf54\ub97c \ub0a9\uc791\ud558\uac8c \ud574 \uc8fc\uc5c8\ub2e4.\n\n> \"\uc815\uc9c1\ud568\uc744 \uac00\uc7a5\ud55c \ub108\ud76c\ub4e4\uc740 \ubaa8\ub4e0 \uc0ac\uae30\uafbc \uc911\uc5d0\uc11c\ub3c4 \uac00\uc7a5 \uc545\uc9c8\uc774\ub2e4.\"\n\n---\n\n## \ud3ec\uc778\ud2b8 37\n\n**\uc99d\uad8c\uc2dc\uc7a5\uc740 \uc5bc\ub8e9\ub35c\ub8e9\ud55c \ubd84\uc704\uae30\uc758 \uc138\uacc4\uc774\uba70 \uac15\uc790\uac00 \uc57d\uc790\ub97c \uc7a1\uc544\uba39\ub294 \uc815\uae00\uc758 \ucd95\uc18c\ud310\uc774\ub2e4.** \ud504\ub85c\uc758 \uc138\uacc4\ub294 \uc601\uc6d0\ud55c \uc2f8\uc6c0\ud130\uc774\uba70 \uc804\uc7c1\ud130\uc774\ub2e4. \uc774 \ud53c\ube44\ub9b0\ub0b4 \ub098\ub294 \uc804\uc7c1\ud130\uc5d0\uc11c \uac00\uc7a5 \uc798 \uc801\uc751\ud558\ub294 \ub450 \ubd80\ub958\ub294 \ubc14\ub85c \uc2dc\uc138 \ud558\ub77d \ud22c\uc790\uc790(\uacf0)\uc640 \uc2dc\uc138 \uc0c1\uc2b9 \ud22c\uc790\uc790(\ud669\uc18c)\uc774\ub2e4.\n\n\ud669\uc18c\ub294 \ud22c\uc790\uc790\uc758 \uc0c1\uc9d5\uc774\ub2e4. \uadf8\ub294 \uc120\ub450\uc5d0\uc11c \ub3cc\uc9c4\ud558\uba70 \uadf8\uc758 \ubfd4\uc744 \uac00\uc9c0\uace0 \ubaa8\ub4e0 \uac83\uc744 \ub192\uc774 \ub358\uc838 \uc62c\ub9ac\ub824 \ud55c\ub2e4. \ud669\uc18c\ub4e4\uc740 \uc2dc\uc138\uac00 \ud558\ub77d\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \uafc8\uc5d0\ub3c4 \uc0c1\uc0c1\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc0c1\uc2b9 \uc7a5\uc5d0 \ud22c\uc790\ud558\ub294 \uc0ac\ub78c\ub4e4\uc740 \ub098\uc911\uc5d0 \uc8fc\uac00\uac00 \ud558\ub77d\ud558\uc5ec \uc785\uac8c \ub418\ub294 \uc190\ud574\ubcf4\ub2e4 \uc99d\uc2dc\uac00 \uc0c1\uc2b9\uc138\uc77c \ub54c \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc544 \uc783\uac8c \ub418\ub294 \ub3c8\uc744 \uba3c\uc800 \uc0dd\uac01\ud558\uae30 \ub9c8\ub828\uc774\ub2e4.\n\n\uc2dc\uc138 \ud558\ub77d \ud22c\uc790\uc790\ub4e4\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc8fc\uac00 \ud558\ub77d\uc73c\ub85c \uace0\ud1b5\uc2a4\ub7ec\uc6cc \ud560 \ub54c\ub9cc \ub3c8\uc744 \ubc8c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc2dc\uc138 \uc0c1\uc2b9 \ud22c\uc790\uc790\ub4e4\uc740 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc190\ud574\uac00 \uc544\ub2c8\ub77c \uae30\uc5c5\uc758 \uc131\uc7a5\uc5d0 \ub530\ub978 \uc8fc\uac00 \uc0c1\uc2b9\uc73c\ub85c\ubd80\ud130 \uc774\uc775\uc744 \uc5bb\ub294\ub2e4. \ud669\uc18c\ub294 \uacf0\uc744 \uc88b\uc544\ud558\uc9c0\ub9cc \uacf0\uc740 \ud669\uc18c\ub97c \uc88b\uc544\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub4e4\uc758 \uc138\uacc4\uad00\uc740 \uadfc\ubcf8\uc801\uc73c\ub85c \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0 \uac19\uc740 \ud604\uc0c1\uc744 \ub2e4\ub974\uac8c \ud574\uc11d\ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 38\n\n\uc2ec\uc0ac\uc219\uace0\ud558\uc5ec \uacb0\uc815\uc744 \ub0b4\ub9ac\ub294 \uc9c0\uc801\uc778 \uc2dc\uc138 \ud558\ub77d \ud22c\uc790\uc790\uc640\ub294 \ub2e4\ub974\uac8c \uc2ec\ub9ac\uc801 \uc2dc\uc138 \ud558\ub77d \ud22c\uc790\uc790\ub4e4\ub3c4 \uc788\ub2e4. **\uc2ec\ub9ac\uc801 \uc2dc\uc138 \ud558\ub77d \ud22c\uc790\uc790\ub4e4\uc740 \uc8fc\uc2dd\ub4e4\uc774 \uacfc\ub300\ud3c9\uac00 \ub418\uc5c8\ub294\uc9c0 \ub610\ub294 \uc800\ud3c9\uac00 \ub418\uc5c8\ub294\uc9c0 \uc544\ubb34\uac83\ub3c4 \ubaa8\ub974\uace0 \uac71\uc815\ub3c4 \ud558\uc9c0 \uc54a\ub294\ub2e4. \uc2dc\uc138 \ud558\ub77d \ud22c\uc790\uc790\uac00 \ub418\uae30\ub85c \ud558\ub294 \uadf8\uc758 \uacb0\uc815\uc740 \uc21c\uc804\ud788 \uac1c\uc778\uc801\uc778 \uc2ec\ub9ac \uc0c1\ud0dc\uc5d0 \ub2ec\ub824\uc788\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 39\n\n\ub354 \uc774\uc0c1\ud55c \uc0ac\ub78c\ub4e4\uc740 \uacf0\uacfc \ud669\uc18c\uac00 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0\uc5d0 \ub300\ud574\uc11c \uc804\ud600 \uad00\uc2ec\uc774 \uc5c6\ub294 \uc0ac\ub78c\ub4e4\uc774\ub2e4. \uadf8\ub4e4\uc740 \uc790\uae30\ub4e4\ub9cc\uc758 \ub3c5\uc790\uc801\uc778 \uc138\uacc4\ub97c \uac16\uace0 \uc788\uc73c\uba70, \uc624\uc9c1 \ub17c\ub9ac\uc801 \uc0dd\uac01\ub9cc\uc73c\ub85c \ub9e4\uc218\ud558\uace0 \ub9e4\ub3c4\ud55c\ub2e4. \ub610 \uba38\ub9bf\uc18d\uc73c\ub85c\ub9cc \uc774\uc724\uacfc \uc190\uc2e4\uc744 \uc7a5\ubd80\uc5d0 \uae30\uc785\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc9c0\uac11\uc740 \uc544\ubb34\uac83\ub3c4 \ub290\ub07c\uc9c0 \ubabb\ud55c\ub2e4. \uc774\ub7ec\ud55c \uac8c\uc784\uafbc\ub4e4\uc740 \uc774\ub860\uc0c1\uc73c\ub85c \uc774\uc724\uc744 \uc5bb\uac8c \ub418\uba74 \ud589\ubcf5\uac10\uc744 \ub290\ub080\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 40\n\n\uc2dc\uc138 \uc0c1\uc2b9 \ud22c\uc790\uc790, \uc2dc\uc138 \ud558\ub77d \ud22c\uc790\uc790 \uc989 \uacf0\uacfc \ud669\uc18c, \uc774\ub4e4 \ubaa8\ub450 \ud22c\uc790\uc790\uac00 \ub420 \uc218 \uc788\ub2e4. **\ud22c\uc790\uc790\ub294 \uc0ac\uc2e4 \uc11c\ubbfc\uc801\uc778 \uc9c1\uc5c5\uc774 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ud558\ub098\uc758 \ucc9c\uc9c1\uc774\ub2e4.** \ud22c\uc790\uc790\ub4e4\uc740 \uadf8\ub4e4\uc758 \ud22c\uc790\ub97c \ud56d\uc0c1 \uc8fc\uac00\uc640 \uc2dc\uc138\uc758 \uc21c\ud658\uc801 \ubcc0\ub3d9\uc5d0 \uc801\uc751\uc2dc\ud0a8\ub2e4.\n\n\ud22c\uc790\uc790\ub294 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc5d0 \ube44\ud574 \ub354 \ub9ce\uc740 \uc544\uc774\ub514\uc5b4\ub97c \uac00\uc9c0\uace0 \uc788\uace0, \ub04a\uc784\uc5c6\uc774 \ubbf8\ub798\uc5d0 \ub300\ud55c \ube44\uc804\uc744 \uadf8\ub9ac\uace0 \uadf8\uc640 \ub9cc\ub098\ub294 \ubaa8\ub4e0 \uac83\ub4e4\uc758 \uc774\ub4dd\uacfc \uc190\uc2e4\uc744 \ub530\uc9c4\ub2e4. \uadf8\ub294 \uc774\ub85c\ubd80\ud130 \ub0b4\ub9b0 \uacb0\ub860\uc744 \ud1a0\ub300\ub85c \ud574\uc11c \uc5b4\ub5a4 \uc8fc\uc2dd\uc744 \uc0ac\uac70\ub098 \ud310\ub2e4. \ub9cc\uc57d \uadf8\uc758 \uc0dd\uac01\uc774 \ub9de\uc558\ub2e4\uba74 \uadf8\ub294 \uc99d\uad8c\uc2dc\uc7a5\uc73c\ub85c\ubd80\ud130 \ub3c8\uc744 \ubc1b\ub294\ub2e4. \ub9cc\uc57d \ud2c0\ub838\ub2e4\uba74 \uadf8\ub294 \uc99d\uad8c\uc2dc\uc7a5\uc5d0 \ubc8c\uae08\uc744 \ub0b8\ub2e4. **\uc774\uac83\uc774 \ud22c\uc790\uc758 \ubcf8\uc9c8\uc774\ub2e4.**\n\n\ube44\uc804\uc774\ub780 \ub3c5\ud2b9\ud558\uace0 \ube44\ud0c0\ud611\uc801\uc778 \uc544\uc774\ub514\uc5b4\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc544\ub2cc \uac83 \uac19\uc544 \ubcf4\uc774\uace0 \uc99d\uc2dc \ub300\uc911\ub4e4\uc740 \uc774\ub97c \ube44\uc6c3\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc0ac\uc2e4\uc774 \ub418\ub294 \uac83\uc774\ub2e4.\n\n> \"\ud22c\uc790\uc790\ub294 \uc808\ub300\ub85c \ubc31\uacfc\uc0ac\uc804\uc774 \ub418\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc62c\ubc14\ub978 \uc21c\uac04\ub4e4\uc5d0 \uad00\ub828\ub41c \uac83\uc744 \uc54c\uc544\uc57c \ud558\uba70, \ub2e8\uc9c0 \ud070 \uadf8\ub9bc\uc744 \uc774\ud574\ud560 \uc218 \uc788\uc73c\uba74 \ub41c\ub2e4. \uac04\ub2e8\ud788 \ub9d0\ud574\uc11c \uadf8\ub294 \uc0dd\uac01\ud558\ub294 \uc0ac\ub78c\uc774\uc5b4\uc57c \ud55c\ub2e4.\"\n\n\ud22c\uc790\uc790\ub294 \ud589\ubcf5\ud558\ub2e4. \uc790\uc2e0\ub9cc\uc758 \uc2dc\uac04\uc744 \uc790\uc720\ub86d\uac8c \ub9c8\uc74c\ub300\ub85c \ucc98\ub9ac\ud558\uba70, \uc548\ub77d\uc758\uc790\uc5d0 \uae30\ubd84 \uc88b\uac8c \uc549\uc544\uc11c \ucc3d\uac00\uc5d0\uc11c \ud22c\uae30\uafbc\ub4e4\uc758 \uc18c\uc74c\uc73c\ub85c\ubd80\ud130 \uc790\uc2e0\uc744 \uba40\ub9ac\ud55c \ucc44 \uc0dd\uac01\uc744 \ud55c\ub2e4. \uadf8\uc758 \ub3c4\uad6c\ub294 \uc804\ud654\uae30\uc640 \ub77c\ub514\uc624, \uadf8\ub9ac\uace0 \uc2e0\ubb38\ubfd0\uc774\ub2e4.\n\n\uc601\uad6d\uc758 \uadc0\uc871\uc73c\ub85c \ucd94\ub300\ub418\uc5c8\uace0 \uac00\uc7a5 \uc704\ub300\ud55c \uad6d\ubbfc \uacbd\uc81c\ud559\uc790\uc600\ub358 \uc874 \uba54\uc774\ub098\ub4dc \ucf00\uc778\uc988\ub3c4 \uc815\uc5f4\uc801\uc778 \ud22c\uc790\uc790\uc600\ub2e4. \ucf00\uc778\uc988 \ucd08\uc0c1\ud654 \uc544\ub798\uc5d0\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \uc601\uad6d \uc815\ubd80\uc758 \ud5cc\uc0ac\uac00 \ubd99\uc5b4\uc788\ub2e4.\n\n> \"\uadf8\ub294 \ub178\ub3d9 \uc5c6\uc774 \uc7ac\uc0b0\uc744 \ubd88\ub838\ub2e4.\"\n\n---\n\n## \ud3ec\uc778\ud2b8 41\n\n\ub9ce\uc740 \uc99d\uad8c\uc2dc\uc7a5 \ucc38\uc5ec\uc790\ub4e4\uc774 \ubbf8\uc2e0\uacfc \uc6b0\uc0c1\uc22d\ubc30\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc778\ub2e4. \ud22c\uc790\uc790\ub294 \uac70\uc758 \ub300\ubd80\ubd84 \ubbf8\uc2e0\uc744 \ubbff\uac8c \ub9c8\ub828\uc774\ub2e4. \uc65c\ub0d0\ud558\uba74 \ud22c\uc790\uc790\ub294 \ubaa8\ub4e0 \uad00\uc810\uc5d0\uc11c \ub17c\ub9ac\uc801\uc774\uace0 \uac00\uc7a5 \ud655\uc2e4\ud55c \ub17c\uc99d\uc744 \uc704\ud574 \ub17c\uc81c\ub97c \uc138\uc6b0\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \ud22c\uc790\uac00 \uc798\ubabb\ub418\uc5c8\ub2e4\ub294 \uac83\uc744 \uc54c\uac8c \ub41c\ub2e4. \uadf8\ub7ec\uba74 \"\uadf8\ub0e5 \uc6b4\uc774 \uc5c6\uc5c8\uc5b4\"\ub77c\uace0 \ub9d0\ud574 \ubc84\ub9b0\ub2e4. \uadf8\ub807\uac8c \uc2e4\ud328\ub97c \ubd88\uc6b4\uc73c\ub85c \ub3cc\ub9b4 \ub54c \uadf8\ub294 \uc774\ubbf8 \ubbf8\uc2e0\uc744 \ubbff\ub294 \uc0ac\ub78c\uc774 \ub41c\ub2e4.\n\n\uc9c1\uad00\uc740 \ub9e4\uc6b0 \uc4f8\ubaa8\uac00 \uc788\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc790\uc2e0\uc774 \ud0c4 \ubc30\uac00 \uc798\ubabb\ub418\uc5c8\ub2e4\ub294 \ub290\ub08c\uc774 \ub4e4\uba74 \uadf8 \ubc30\uc5d0\uc11c \ub6f0\uc5b4\ub0b4\ub9b0\ub2e4. **\uadf8\uac83\uc740 \ud655\uc2e0\uacfc \uc9c1\uad00\uc758 \ud63c\ud569\uc774\ub2e4.** \ud22c\uc790\uc790\ub294 \uc5ec\uc131\uc758 \ub9d0 \ud55c\ub9c8\ub514\ub3c4 \uc8fc\uc758 \uae4a\uac8c \ub4e4\uc5b4\uc57c \ud55c\ub2e4. \uc5ec\uc131\ub4e4\uc740 \uc544\uc8fc \uc12c\uc138\ud55c \uc9c1\uad00\uacfc \ubcf8\ub2a5\uc744 \uac00\uc9c0\uace0 \uc788\uc73c\uba70 \uadf8\uac83\uc774 \ub0a8\uc790\ub4e4\uc758 \ub17c\ub9ac\uc801 \ud655\uc2e0\uc744 \ubcf4\ucda9\ud574 \uc904 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n**\uc9c1\uad00\uc740 \uc2e4\uc81c\ub85c \ubb34\uc758\uc2dd\uc801\uc778 \ub17c\ub9ac\uc640 \uacb0\ucf54 \ub2e4\ub974\uc9c0 \uc54a\ub2e4.** \ubb34\uc758\uc2dd\uc758 \ub17c\ub9ac\ub294 \ub2e4\uc2dc\uae08 \uacbd\ud5d8\uacfc \ud63c\ud569\ub418\uc5b4 \uc7a5\uae30\uac04\uc758 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c\uc758 \uacbd\ud5d8\uacfc \uc0b6\uc758 \uacbd\ud5d8\uc774 \ud569\uccd0\uc9c4 \ud558\ub098\uc758 \uadf8\ub9bc\uc744 \uadf8\ub824\ub0b8\ub2e4. \ubc24\uc911\uc5d0 \ubb34\uc758\uc2dd\uc801 \uc0ac\uace0\ub97c \ud1b5\ud558\uc5ec \uc5b4\ub5a4 \uc544\uc774\ub514\uc5b4\uac00 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub9ac\uace0 \uc544\uce68\uc5d0 \uadf8 \uc544\uc774\ub514\uc5b4\ub294 \uc2e4\uc81c\ub85c \uc874\uc7ac\ud558\uac8c \ub41c\ub2e4. \uc774\uac83\uc744 \uc0ac\ub78c\ub4e4\uc740 \uc9c1\uad00, \uc601\uac10\uc774\ub77c\uace0 \ubd80\ub978\ub2e4.\n\n\uadf8\ub7ec\ub098 \ud63c\uc790\uc11c \ud658\uc0c1 \uc18d\uc73c\ub85c \ube60\uc838\ub4dc\ub294 \uac83\uc740 \uc704\ud5d8\ud55c \uc77c\uc774\ub2e4. \ubbf8\uc2e0\uc744 \uace0\uc815\ub41c \uc544\uc774\ub514\uc5b4\uc640 \uacb0\ud569\uc2dc\ucf1c \uadf8\uac83\uc744 \uc6b0\uc0c1\ucc98\ub7fc \uc22d\ubc30\ud558\uac8c \ub418\uba74 \uadf8\uac83\uc740 \ubcd1\uc801\uc778 \uc0c1\ud0dc\uac00 \ub41c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 42\n\n\uc624\ub298\ub0a0\uc5d0\ub3c4 \uc5f0\uae08\uc220\uc0ac, \uc810\uc131\uc220\uc0ac\uac00 \uc874\uc7ac\ud55c\ub2e4. \ud2b9\ud788 \uac8c\uc784\uafbc \uc911\uc5d0 \uadf8\ub7f0 \uc0ac\ub78c\ub4e4\uc774 \uc788\ub2e4. \ub2e8\uc9c0 \ubc29\ubc95\uc774 \ubcc0\ud588\uc744 \ubfd0\uc774\ub2e4. \uc5f0\uae08\uc220\uc0ac\ub294 \uad6c\ub9ac\ub85c \uae08\uc744 \ub9cc\ub4e4\ub824 \ud588\uc73c\uba70, \uc810\uc131\uc220\uc0ac\ub4e4\uc740 \ubcc4\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \uc608\uc5b8\uc744 \ud558\ub824 \ud588\ub2e4. **\uac8c\uc784\uafbc\ub4e4\uc740 \uc774\ub860\uc744 \uac00\uc9c0\uace0 \uae08\uac12\uc744 \uc62c\ub9ac\ub824 \ud558\uba70, \ucc28\ud2b8\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \uc608\uc5b8\uc744 \ud558\ub824 \ud55c\ub2e4.** \ub098\ub294 \ud559\ubb38\uc758 \uac00\uc8fd\uc744 \ub4a4\uc9d1\uc5b4 \uc4f4 \uc774 \uac8c\uc784\uafbc\ub4e4\uc744 \ubbf8\uce5c \uc0ac\ub78c\ub4e4\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \ub9cc\uc57d \uadf8\ub4e4\uc774 \uadf8\uac83\uc744 \uc2dc\uc2a4\ud15c\ud654\ud558\uc5ec \ub3c8\uc744 \ubc1b\uace0 \ud310\ub2e4\uba74, \uadf8\uac83\uc740 \ubbf8\uce5c \uc9d3\uc77c \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0ac\uae30\uafbc\uc774\uae30\uae4c\uc9c0 \ud558\ub2e4.\n\n> \"\ucc28\ud2b8\ub97c \ud1b5\ud574 \uc5b4\uc81c\uac00 \uc5b4\ub5a0\ud588\uace0 \uc624\ub298\uc774 \uc5b4\ub5a0\ud55c\uc9c0\ub97c \uac00\uc7a5 \ud655\uc2e4\ud558\uac8c \ubcfc \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc774\uc0c1\uc740 \uc5c6\ub2e4.\"\n\n> \"\uc5d8\ub9ac\uc5b4\ud2b8 \ud30c\ub3d9\uc740 \ub0b4 \ub208\uc5d0\ub294 \ucee4\ud53c\ub97c \ub0b4\ub9ac\uace0 \ub0a8\uc740 \ucc0c\uaebc\uae30\ub97c \uac00\uc9c0\uace0 \ubbf8\ub798\ub97c \uc77d\ub294 \uac83\uacfc \ub3d9\uc77c\ud560 \ubfd0\uc774\ub2e4.\"\n\n> **\"\ucc28\ud2b8 \ubd84\uc11d\uac00\ub4e4\uc740 \uc80a\uc5b4\uc11c\ub294 \uc99d\uad8c\uc778, \ub299\uc5b4\uc11c\ub294 \uac70\uc9c0\uac00 \ub420 \ubfd0\uc774\ub2e4.\"**\n\n---\n\n## \ud3ec\uc778\ud2b8 43\n\n\uc99d\uad8c\uc2dc\uc7a5\ub3c4 \uc911\ub3c5\ub420 \uc218 \uc788\ub2e4. \uc65c\ub0d0\ud558\uba74 \uadf8\uac83\uc740 \ub9e4\uc6b0 \ud2b9\uc774\ud55c \ubd84\uc704\uae30\uac00 \uc9c0\ubc30\ud558\ub294 \uacf3\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ub098\uc758 \ud55c \uce5c\uad6c\ub294 \uc99d\uad8c\uc2dc\uc7a5 \uc911\ub3c5\uc790\uc600\ub2e4. \uadf8\ub294 \ucca0\uac15 \ubd84\uc57c\uc5d0\uc11c \uc77c\uc744 \ud558\uc600\uc73c\uba70 \ud55c\uad6d \uc804\uc7c1 \ub3d9\uc548\uc5d0 \ud070 \ubd80\ud638\uac00 \ub418\uc5c8\ub2e4.\n\n\ub098\ub294 \uce5c\uad6c\uc5d0\uac8c \uacbd\uace0\ud588\ub2e4.\n\n> \"\ud55c\uad6d \uc804\uc7c1\ub3c4 \uc601\uc6d0\ud788 \uc9c4\ud589\ub418\uc9c0 \uc54a\uc744 \uac83\uc774\uba70, \ucc28\ub840\ub3c4 \uc5b8\uc820\uac00\ub294 \ud2c0\ub9bc\uc5c6\uc774 \ub098\uc758 \uc870\uc5b8\uc744 \uad6c\ud560 \uac83\uc77c\uc138. \uadf8\ub7ec\ub098 \uadf8 \uc804\uc5d0 \uc790\ub124\ub294 \uc8fc\uc2dd\uc744 \uc774\ud574\ud560 \uc218 \uc788\uc5b4\uc57c \ud560 \uac83\uc77c\uc138.\"\n\n\ub098\ub294 \uba87 \uac00\uc9c0 \uc885\ubaa9\uc744 \ucd94\ucc9c\ud574 \uc8fc\uc5c8\ub2e4. \uc5bc\ub9c8 \uc9c0\ub098\uc9c0 \uc54a\uc544 \uadf8 \uc885\ubaa9\ub4e4 \uc911 \uc5b4\ub290 \uac83\uc740 10\ubc30, \uc5b4\ub290 \uac83\uc740 100\ubc30\uac00 \ub418\uc5c8\ub2e4. \uccab \ubc88\uc9f8 \ud22c\uc790\uc5d0\uc11c \uace7\ubc14\ub85c \uc88b\uc740 \uacb0\uacfc\uac00 \ub098\uc624\uc790 \ub0b4 \uce5c\uad6c\ub294 \uc810\uc810 \ub354 \ub9ce\uc740 \uc8fc\uc2dd\uc744 \uc0ac\ub4e4\uc600\ub2e4. \ub9e8 \ucc98\uc74c\uc5d0\ub294 \uc790\uc2e0\uc774 \ubcf4\uc720\ud55c \ud604\uae08\uc73c\ub85c \ud558\ub354\ub2c8, \uc810\uc810 \uc2e0\uc6a9\uc73c\ub85c \uc0c0\ub2e4.\n\n\uadf8\uc758 \uc99d\uad8c \uc0ac\uc5c5\uc774 \ucd5c\uace0\uc810\uc5d0 \ub3c4\ub2ec\ud588\uc744 \ub54c \uadf8\ub294 \ub2e8 \ud558\ub8e8 \uc0ac\uc774\uc5d0 \uac00\uc871 1\ub144 \uc608\uc0b0\uc758 5\ubc30\ub97c \ubc8c\uace0 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub2e4 \uc99d\uad8c\uc2dc\uc7a5\uc774 \uc57d\uc138\uc7a5\uc774 \ub418\uc5b4 \uac14\ub2e4. \uc774\uc775\uc740 \uc810\uc810 \uc904\uc5b4\ub4e4\uc5c8\ub2e4. \uadf8\ub294 \uacb0\uad6d \uc2e0\uacbd\uc1e0\uc57d\uc73c\ub85c \ubcd1\uc6d0\uc5d0 \uc2e4\ub824 \uac14\ub2e4. \uadf8\uc758 \uac00\uc871\uc740 \ubaa8\ub4e0 \ud22c\uc790\uc790\uc0b0\uc744 \uccad\uc0b0\ud558\uae30\ub85c \uacb0\uc815\ud588\ub2e4. \uadf8\ub294 \ubaa8\ub4e0 \uc8fc\uc2dd\uc744 \ud314\uc558\uace0 \uc644\uc804\ud788 \uc644\ucf8c\ub418\uc5b4 \uac00\uc871 \uacc1\uc73c\ub85c \ub3cc\uc544\uc654\ub2e4.\n\n**\uc8fc\uc2dd\uc744 \uac00\uc9c0\uace0 \uc788\uc73c\uba74 \uc2dc\uc138\uac00 \ub5a8\uc5b4\uc9c8\uae4c \ubd10 \ubd88\uc548\ud574\ud558\uace0, \uc8fc\uc2dd\uc744 \uac00\uc9c0\uace0 \uc788\uc9c0 \uc54a\uc73c\uba74 \uc2dc\uc138\uac00 \uc62c\ub77c\uac08\uae4c \ubd10 \ubd88\uc548\ud574\ud55c\ub2e4.** \uc8fc\uc2dd\uc5d0 \uc911\ub3c5\ub41c \uc0ac\ub78c\ub4e4\uc740 \uc99d\uc2dc \uce68\uccb4 \ud6c4\uc5d0\ub3c4 \uc5b8\uc81c\ub098 \uacfc\uac70\uc758 \ubaa8\ub4e0 \uc0c1\ucc98\ub4e4\uc744 \ub2e4 \uc78a\uc5b4\ubc84\ub9ac\uace0 \ubd88\ub098\ubc29 \uac19\uc774 \uc99d\uad8c\uc2dc\uc7a5\uc5d0 \ubab0\ub824\ub4e0\ub2e4.\n\n> \"\uadf8\ub7fc \uc99d\uad8c\uc2dc\uc7a5\uc740 \ubbf8\uce58\uad11\uc774\ub4e4, \ubc14\ubcf4\ub4e4 \ucc9c\uc9c0\uc778\uac00? \uc544\ub9c8\ub3c4 \uadf8\ub7f4 \uac83\uc774\ub2e4. \uc65c\ub0d0\ud558\uba74 \ubbf8\uce58\uad11\uc774\uc640 \ubc14\ubcf4\ub4e4\uc774 \uc5c6\ub294 \uc138\uc0c1\uc740 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc744 \uac83\uc774\uba70, \uadf8\ub4e4\uc774 \uc5c6\ub294 \uc99d\uad8c\uc2dc\uc7a5\uc740 \uc544\ubb34\ub7f0 \uc758\ubbf8\uac00 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub4e4\uc774 \uc5c6\ub2e4\uba74 \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc774\uc775\uc740 \ub2e4 \uc5b4\ub514\uc11c \uc5bb\uc744 \uac83\uc774\uba70, \uc99d\uad8c\uc2dc\uc7a5\uc774 \uc874\uc7ac\ud560 \uc218\uac00 \uc788\uaca0\ub294\uac00?\"\n\n---\n\n## \ud3ec\uc778\ud2b8 44\n\n\uacbd\uc81c\ud559 \ud559\uc704\ub97c \ub530\ub294 \uac83\uc740 \uc4f8\ubaa8\uc5c6\ub2e4. \ub2e8\uc9c0 \uadf8\ub4e4\uc758 \uba85\ud568\uc5d0 \ud55c \uc904 \uc4f8 \ub9d0\uc774 \uc0dd\uae38 \ubfd0\uc774\ub2e4. \uadf8\ub4e4\uc740 \uc881\uc740 \uc2dc\uc57c\ub97c \uac00\uc9c0\uace0 \uc0b4\uc544\uac00\uba70 \ud3ed\ub113\uac8c \uc0dd\uac01\ud558\uc9c0 \ubabb\ud55c\ub2e4.\n\n**\uacbd\uc81c\ud559\uc744 \uacf5\ubd80\ud558\uace0 \uc99d\uad8c \uc2dc\uc7a5\uc5d0 \uc9c4\ucd9c\ud558\uace0\uc790 \ud558\ub294 \ubaa8\ub4e0 \uc80a\uc740\uc774\uc5d0\uac8c \ub098\ub294 \uc774\ub807\uac8c \ucda9\uace0\ud558\uace0 \uc2f6\ub2e4. \ub300\ud559\uc5d0\uc11c \ubc30\uc6e0\ub358 \ubaa8\ub4e0 \ud559\ubb38\uc801 \uc9c0\uc2dd\uc740 \uacfc\uac10\ud558\uac8c \uc78a\uc5b4\ubc84\ub824\ub77c. \uadf8\uac83\uc740 \uc99d\uad8c \uc2dc\uc7a5\uc5d0\uc11c \ub2e8\uc9c0 \uc9d0\uc774 \ub420 \ubfd0\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 45\n\n> \"\ub098\ub294 \uc815\ubcf4\ub97c \uc790\ubc1c\uc801\uc73c\ub85c \uc54c\ub824\uc900 \uc801\uc774 \uac70\uc758 \uc5c6\ub2e4. \uc65c\ub0d0\ud558\uba74 \uc815\ub9d0 \uc815\ud655\ud55c \uc815\ubcf4\ub294 \ud558\ub098\ub3c4 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4.\"\n\n**\ub9cc\uc57d \ub2f9\uc2e0\uc5d0\uac8c \uce5c\uad6c\uac00 \uc788\ub2e4\uba74 \uadf8\uc5d0\uac8c \ubb3c\uace0\uae30\ub97c \uc120\ubb3c\ud558\ub77c. \ud558\uc9c0\ub9cc \uadf8 \uce5c\uad6c\ub97c \uc815\ub9d0\ub85c \uc0ac\ub791\ud55c\ub2e4\uba74 \uadf8 \uce5c\uad6c\uc5d0\uac8c \ubb3c\uace0\uae30\ub97c \uc7a1\ub294 \ubc29\ubc95\uc744 \uc54c\ub824 \uc918\ub77c.**\n\n\ub098\ub294 \ubd80\uc815\uc801\uc778 \uc815\ubcf4\uc640 \uacbd\uace0\ub4e4\uc740 \uc790\ubc1c\uc801\uc73c\ub85c \ub9d0\ud574 \uc8fc\uc5c8\ub2e4. \ub098\ub294 IOS\ub77c\ub294 \ubca4\ucc98\uae30\uc5c5\uc5d0 \ub300\ud55c \uacbd\uace0\ub97c \ub300\ub193\uace0 \ud558\uc600\ub2e4. IOS \ub300\ud45c\ub294 \ub098\ub97c \ud30c\uba78\uc2dc\ud0a4\uaca0\ub2e4\uace0 \ud611\ubc15 \ud3b8\uc9c0\ub97c \ubcf4\ub0c8\ub2e4. \ud558\uc9c0\ub9cc \uacb0\uad6d IOS\uc5d0 \ub300\ud55c \ub098\uc758 \uacbd\uace0\ub294 \ub9de\uc558\ub2e4.\n\n> \"\ub9cc\uc57d \uc5b4\ub5a4 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\ubcf4\ub2e4 24\uc2dc\uac04 \uba3c\uc800 \uc633\uc558\ub2e4\uba74, \uadf8\ub294 \uadf8 24\uc2dc\uac04 \ub3d9\uc548 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc5d0 \uc758\ud574 \uc5b4\ub9ac\uc11d\ub2e4\uace0 \uc5ec\uaca8\uc9c4\ub2e4.\"\n\n\ub300\ubd80\ubd84\uc758 \ud380\ub4dc \ub9e4\ub2c8\uc800\ub4e4\uc740 \uc0c1\ub2f9\ud788 \uc80a\ub2e4. \uadf8\ub4e4\uc740 \uc99d\uad8c\uc2dc\uc7a5\uc774 \uc5b4\ub824\uc6cc\uc9c8 \uacbd\uc6b0 \uc5b4\ub5bb\uac8c \ud5e4\uccd0\ub098\uac00\uc57c \ud558\ub294\uc9c0 \uc804\ud600 \ubaa8\ub978\ub2e4. \ud380\ub4dc \ub9e4\ub2c8\uc800\ub4e4\uc740 \ub0a8\uc758 \ub3c8\uc744 \uac16\uace0 \uc0ac\uc5c5\uc744 \ud55c\ub2e4. \uadf8\ub4e4\uc740 \uc8fc\uc2dd\ud22c\uc790\uc5d0 \ub300\ud574 \uc544\ubb34\uac83\ub3c4 \ubaa8\ub974\ub294 \uc18c\uc561 \ud22c\uc790\uc790\ub4e4\uc744 \uc0c1\ub300\ub85c \uc5f0\uac04 15%\uc758 \uc774\uc724\uc744 \ubc1b\uac8c \ub420 \uac83\uc774\ub77c\uace0 \ud655\uc5b8\ud55c\ub2e4.\n\n> \"\uc18c\uc561 \ud22c\uc790\uc790\ub4e4\uc5d0\uac8c \uace0\ud1b5\uc744 \uc548\uaca8\uc900 \uacb0\uacfc \uc545\uc9c8 \ud380\ub4dc \ub9e4\ub2c8\uc800\ub294 \uc5c4\uccad\ub09c \ubd80\ub97c \ub204\ub9b0\ub2e4. \ud380\ub4dc \ub9e4\ub2c8\uc800\ub4e4\uc758 \ubed4\ubed4\ud568\uacfc \uc18c\uc561 \ud22c\uc790\uc790\ub4e4\uc758 \uc5b4\ub9ac\uc11d\uc74c\uc774 \uc774\ub7ec\ud55c \uacb0\uacfc\ub97c \ub0b3\ub294 \uac83\uc774\ub2e4.\"\n\n---\n\n## \ud3ec\uc778\ud2b8 46\n\n\ub098\ub294 \uc99d\uad8c\uc2dc\uc7a5\uc758 \uc815\ubcf4\ub97c \uc808\ub300\ub85c \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uc815\ubcf4\ub780 \ud138\uc5b4\ubc84\ub9b4 \uc8fc\uc2dd\uc744 \uac16\uace0 \uc788\uac70\ub098 \ub610\ub294 \uc218\uc218\ub8cc\ub97c \ucc59\uae30\uae30\ub97c \uc6d0\ud558\ub294 \uc740\ud589\uacfc \ube0c\ub85c\ucee4\ub4e4\uc758 \uc77c\uc774\ub2e4. **\uadf8\ub7ec\ub098 \ub0b4 \ud559\uc0dd\ub4e4\uc774 \ub098\ub97c \ud1b5\ud574 \uc0dd\uac01\ud558\uace0 \ubd84\uc11d\ud558\uace0, \ub05d\uae4c\uc9c0 \uc790\uae30\uc758 \uc0dd\uac01\uc744 \uace0\uc218\ud558\uac8c \ub418\ub294 \ubc95\uc744 \ubc30\uc6b4\ub2e4\uba74 \uc88b\uaca0\ub2e4.**\n\n> \"\uc0ac\ub78c\uc740 \uaf2d \ubd80\uc790\uc77c \ud544\uc694\uac00 \uc5c6\ub2e4. \uadf8\ubcf4\ub2e4\ub294 \uc790\uc720\ub85c\uc6cc\uc57c \ud55c\ub2e4.\"\n\n> \"\uc0c8\ub85c \uc0b0 \ube57\uc790\ub8e8\uac00 \uc798 \uc4f8\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\uace0, \uc9c0\uae08\uae4c\uc9c0 \uc4f8\uc5b4 \ub2f3\uc544\ubc84\ub9b0 \ube57\uc790\ub8e8\uac00 \uc798 \uc4f8\ub9b0\ub2e4.\" (\uacbd\ud5d8\uc758 \uac00\uce58)\n\n\ub098\uc774\uac00 \ub4e4\uba74 \uc88b\uc740 \uc810\uc740 \ubb34\uc5c7\uc77c\uae4c. \ub098\uc774\uc640 \ud568\uaed8 \uc77c\ubc18\uc801\uc778 \uc2ec\ub9ac\uc801 \uc785\uc7a5\uacfc \uc2dc\uac04\uc5d0 \ub300\ud55c \ub290\ub08c\uc774 \ubcc0\ud55c\ub2e4. \uc80a\uc740 \uc2dc\uc808\uc5d0\ub294 \ube68\ub9ac \ub3c8\uc744 \ubc84\ub294 \uac83\uc774 \uae09\uc120\ubb34\uc600\ub2e4. \ubaa8\ud5d8\uc801\uc774\uace0 \uc704\ud5d8\uc774 \uc874\uc7ac\ud558\ub294 \ud22c\uc790\ub97c \ud1b5\ud574 \uc0b4\uc544\uc788\uc74c\uc744 \ub290\uaf08\uc73c\uba70, \uac8c\uc784\uc5d0 \uc560\ucc29\uc744 \ub290\uaf08\uace0 \ub9e4\uc6b0 \ub2e8\uae30\uc801\uc73c\ub85c \uc0ac\uace0\ud588\ub2e4.\n\n\uc624\ub298\ub0a0\uc758 \ub098\ub294 \ub0c9\uc815\ud568\uacfc \uc77c\uc885\uc758 \ucca0\ud559\uc801 \uc785\uc7a5\uc744 \uac00\uc9c0\uace0 \ubcf8\ub2e4. \uc774\uc81c\ub294 \uc7a5\uae30\uc801\uc73c\ub85c \uc0dd\uac01\ud558\uace0 1\ub144 \ub2e8\uc704\ub85c \uacc4\ud68d\ud55c\ub2e4. 1\ub144 \ud6c4\uc5d0 \ub0b4\uac00 \uc0b4\uc544 \uc788\uc744\uc9c0 \uc7a5\ub2f4\ud560 \uc218 \uc5c6\ub2e4. \uc2dc\uac04\uc740 \ub108\ubb34\ub098\ub3c4 \ube68\ub9ac \ud758\ub7ec\uac00\uc9c0\ub9cc \ub3c8\uc740 \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4. **\uc65c\ub0d0\ud558\uba74 \ub098\ub294 \ub3c8\uc5d0 \ub300\ud574\uc11c\ub77c\uba74 \ub300\ub2e8\ud55c \uc778\ub0b4\uc2ec\uc744 \uac00\uc9c0\uace0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.**\n\n\ud55c\ubc88\uc740 25\uc0b4\uc758 \uc80a\uc740\uc774\uac00 \ub098\uc5d0\uac8c \"\uc800\uc640 \ubc14\uafb8\uace0 \uc2f6\uc9c0 \uc54a\uc73c\uc138\uc694?\"\ub77c\uace0 \ubb3c\uc5c8\ub2e4. \ub098\ub294 \"\ubb3c\ub860 \ubc14\uafb8\uace0 \uc2f6\uc9c0. \ub098\uc758 \uacbd\ud5d8\uacfc \ub098\uc758 \uccb4\ud5d8\uc744 \uc628\uc804\ud788 \uac00\uc9c0\uace0 \uac08 \uc218 \uc788\ub2e4\uba74 \ub9d0\uc774\uc57c\"\ub77c\uace0 \ub300\ub2f5\ud588\ub2e4. \uadf8\ub294 \ub098\uc774\uac00 \uc2a4\uc2a4\ub85c\uc5d0\uac8c \uc990\uac70\uc6c0\uc744 \uac00\uc838\ub2e4 \uc900\ub2e4\ub294 \uac83\uc744 \uc54c\uc9c0 \ubabb\ud588\ub2e4.\n\n---\n\n*\uc815\ub9ac: \uc720\ud29c\ube0c \uc790\ub9c9 \uc6d0\ubb38\uc744 \ubc14\ud0d5\uc73c\ub85c \ub9de\ucda4\ubc95\u00b7\ub744\uc5b4\uc4f0\uae30\ub97c \uad50\uc815\ud558\uace0, \ud575\uc2ec \ub0b4\uc6a9\uc744 \ud3ec\uc778\ud2b8\ubcc4\ub85c \uc7ac\uad6c\uc131\ud55c \uc815\ub9ac\ubcf8\uc785\ub2c8\ub2e4.*\n"
